/* FoxiOra — local-first shift scheduler. Sections: STORAGE · PARSER · SCHEDULE/CONFLICTS · UI.
   Times are stored as epoch-ms segments, so old shifts keep their real times if a code is later edited. */
const $=s=>document.querySelector(s), DAY=864e5;
const DEF=[['N','Night','19:30-08:00'],['D','Morning','07:30-14:30'],['E','Evening','14:00-20:00'],['n','Short night','20:00-24:00'],['M','Leave','leave'],['S','Sick leave','leave'],['OFF','Day off','off'],['*','Day off','off'],['-','Day off','off']];
const VER='v12.15';
const bootStarted=Date.now();
const DEFAULT_COMBOS=['DE','EN','En'];
const DS=()=>({wps:[],shifts:[],events:[],mates:[],gap:120,cal:'j',theme:'auto',lang:'fa',ver:3,myname:'',h24:true,fdow:6,cross:true,same:false,fh:2,weekend:[5],holidays:true,learnOCR:true,themePlaces:true,rosterDays:{},rosterPeriods:[],ocrMemory:{version:1,glyphs:[],names:[]}});
let S=DS(),tab='today',cm=new Date(),sel='',vm='month',calendarWorkplace='',daySelected=false;

/* ---------- STORAGE (IndexedDB, one state object; swap later for per-table stores) ---------- */
const db=()=>new Promise((r,j)=>{const q=indexedDB.open('shiftfox',1);q.onupgradeneeded=()=>q.result.createObjectStore('kv');q.onsuccess=()=>r(q.result);q.onerror=j});
async function load(){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('kv'),q=tx.objectStore('kv').get('state');let value;q.onsuccess=()=>value=q.result;tx.oncomplete=()=>{d.close();resolve(value)};tx.onerror=tx.onabort=()=>{d.close();reject(tx.error||Error('Load failed'))}})}
async function save(){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('kv','readwrite');tx.objectStore('kv').put(S,'state');tx.oncomplete=()=>{d.close();resolve()};tx.onerror=tx.onabort=()=>{d.close();reject(tx.error||Error('Save failed'))}})}

/* Reversible roster changes: small field patches, persisted with the same state. */
const UNDO_KEYS=['wps','shifts','mates','events','rosterDays','onboarding','swapHistory','ocrMemory','rosterPeriods','myname'];
const UNDO_ARRAYS=['wps','shifts','mates','events','swapHistory'];
const own=(o,k)=>o!=null&&Object.prototype.hasOwnProperty.call(o,k);
const copyJSON=v=>v===undefined?undefined:JSON.parse(JSON.stringify(v));
const sameJSON=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
function beginChange(en,fa,keys){return{label:{en,fa},keys,history:copyJSON(S.undoHistory),before:Object.fromEntries(keys.map(k=>[k,copyJSON(S[k])]))}}
function finishChange(change){const patches=[],value=(exists,v)=>exists?{exists:true,value:copyJSON(v)}:{exists:false};
 const diff=(a,b,aExists,bExists,base,path=[])=>{if(aExists===bExists&&sameJSON(a,b))return;
  if(aExists&&bExists&&a&&b&&typeof a==='object'&&typeof b==='object'&&!Array.isArray(a)&&!Array.isArray(b)){for(const k of new Set([...Object.keys(a),...Object.keys(b)]))diff(a[k],b[k],own(a,k),own(b,k),base,[...path,k]);return}
  patches.push({...base,path,before:value(aExists,a),after:value(bExists,b)});
 };
 for(const key of change.keys){const a=change.before[key],b=S[key];if(UNDO_ARRAYS.includes(key)&&Array.isArray(a)&&Array.isArray(b)){const prev=new Map((a||[]).map((x,i)=>[x.id,{x,i}])),next=new Map((b||[]).map(x=>[x.id,x]));for(const id of new Set([...prev.keys(),...next.keys()]))diff(prev.get(id)?.x,next.get(id),prev.has(id),next.has(id),{key,id,index:prev.get(id)?.i??(b||[]).findIndex(x=>x.id===id)})}else diff(a,b,a!==undefined,b!==undefined,{key})}
 if(!patches.length)return false;
 S.undoHistory=Array.isArray(S.undoHistory)?S.undoHistory:[];S.undoHistory.push({id:'change'+Date.now()+Math.random().toString(36).slice(2,6),at:Date.now(),label:change.label,patches});S.undoHistory=S.undoHistory.slice(-20);
 while(S.undoHistory.length>1&&JSON.stringify(S.undoHistory).length>1500000)S.undoHistory.shift();return true;
}
let changeSaving=false;
async function commitChange(change){
 if(changeSaving){for(const key of change.keys)if(change.before[key]===undefined)delete S[key];else S[key]=change.before[key];return false}
 changeSaving=true;const editor=inlineEditor,buttons=[...document.querySelectorAll('button')].filter(b=>!b.disabled);buttons.forEach(b=>b.disabled=true);
 finishChange(change);
 try{await save();showChangeFeedback(T2(enLabel(change.label)+' saved',faLabel(change.label).startsWith('حذف ')?faLabel(change.label).slice(4)+' حذف شد':faLabel(change.label)+' ثبت شد'),true);return true}
 catch{for(const key of change.keys)if(change.before[key]===undefined)delete S[key];else S[key]=copyJSON(change.before[key]);if(change.history===undefined)delete S.undoHistory;else S.undoHistory=change.history;
  showChangeFeedback(T2('Could not save. Your draft is still here; try again.','ذخیره نشد؛ نوشته‌هایتان اینجاست. دوباره امتحان کنید.'));render();if(editor&&editor.view===inlineView())mountInline(editor);return false}
 finally{changeSaving=false;buttons.forEach(b=>b.disabled=false)}
}
async function saveSettings(patch){if(changeSaving||undoBusy)return false;const fields=[...document.querySelectorAll('#v input[id],#v select[id],#v textarea[id]')].map(e=>({id:e.id,value:e.value,checked:e.checked})),before=Object.fromEntries(Object.keys(patch).map(k=>[k,copyJSON(S[k])]));changeSaving=true;Object.assign(S,patch);try{await save();render();return true}catch{for(const [key,value]of Object.entries(before))if(value===undefined)delete S[key];else S[key]=value;render();for(const field of fields){const input=document.getElementById(field.id);if(input){input.value=field.value;if(input.type==='checkbox')input.checked=field.checked}}showChangeFeedback(T2('Could not save this setting. Please try again.','این تنظیم ذخیره نشد؛ دوباره امتحان کنید.'));return false}finally{changeSaving=false}}
function saveQuietly(){return save().catch(()=>showChangeFeedback(T2('Could not save yet. Please try again.','هنوز ذخیره نشد؛ دوباره امتحان کنید.')))}
async function clearData(){if(changeSaving||!confirm(T2('Delete all schedules and settings?','همهٔ برنامه‌ها و تنظیمات حذف شوند؟')))return;const previous=S;S=DS();try{await save();inlineDrafts.clear();inlineEditor=null;render()}catch{S=previous;render();showChangeFeedback(T2('Could not save. Your data is still here.','ذخیره نشد؛ اطلاعاتتان هنوز اینجاست.'))}}
const enLabel=label=>label?.en||'Change',faLabel=label=>label?.fa||'تغییر';
const undoLabel=record=>T2(enLabel(record?.label),faLabel(record?.label));
function undoRecord(){return Array.isArray(S.undoHistory)?S.undoHistory.at(-1):null}
function readUndoPatch(p){let v=p.id==null?S[p.key]:(S[p.key]||[]).find(x=>x.id===p.id),exists=p.id==null?own(S,p.key):v!==undefined;
 for(const k of p.path){exists=exists&&own(v,k);v=exists?v[k]:undefined}return exists?{exists:true,value:v}:{exists:false};}
function validUndoPatch(p){if(!p||!UNDO_KEYS.includes(p.key)||!Array.isArray(p.path)||!p.path.every(k=>typeof k==='string'&&!['__proto__','constructor','prototype'].includes(k))||!p.before||!p.after||typeof p.before.exists!=='boolean'||typeof p.after.exists!=='boolean'||(p.id!=null&&(!UNDO_ARRAYS.includes(p.key)||!Array.isArray(S[p.key]))))return false;
 if(p.path.length){let parent=p.id==null?S[p.key]:(S[p.key]||[]).find(x=>x.id===p.id);for(const k of p.path.slice(0,-1))parent=parent?.[k];if(!parent||typeof parent!=='object')return false}return true;
}
function applyUndoPatch(p){const b=p.before;if(!p.path.length){if(p.id!=null){const list=S[p.key],i=list.findIndex(x=>x.id===p.id);if(i>=0)list.splice(i,1);if(b.exists)list.splice(Math.min(Math.max(p.index||0,0),list.length),0,copyJSON(b.value));}else if(b.exists)S[p.key]=copyJSON(b.value);else delete S[p.key];return}
 let v=p.id==null?S[p.key]:S[p.key].find(x=>x.id===p.id);for(const k of p.path.slice(0,-1))v=v[k];const key=p.path.at(-1);if(b.exists)v[key]=copyJSON(b.value);else delete v[key];
}
let undoBusy=false,feedbackTimer;
async function undoLastChange(){const record=undoRecord();if(!record||undoBusy||changeSaving||sc.busy||tc.busy)return false;
 if(!Array.isArray(record.patches)||!record.patches.every(p=>validUndoPatch(p)&&sameJSON(readUndoPatch(p),p.after))){alert(T2('This part of the schedule has changed again. It cannot be restored safely.','این بخش از برنامه دوباره تغییر کرده؛ امکان برگرداندن این تغییر نیست.'));return false}
 const rollback=Object.fromEntries([...new Set(record.patches.map(p=>p.key)),'undoHistory'].map(k=>[k,copyJSON(S[k])]));undoBusy=true;try{const removed=record.patches.filter(p=>p.id!=null&&!p.path.length&&p.before.exists&&!p.after.exists);for(const p of [...record.patches].reverse().filter(p=>!removed.includes(p)))applyUndoPatch(p);for(const p of removed.sort((a,b)=>a.key.localeCompare(b.key)||a.index-b.index))applyUndoPatch(p);S.undoHistory.pop();tc.res=null;tc.dates=tc.dates.filter(id=>S.shifts.some(h=>h.id===id));tc.notice='';await save();closeDialog();render();showChangeFeedback(T2('Change undone','تغییر برگردانده شد'));return true}catch{for(const [key,value]of Object.entries(rollback))if(value===undefined)delete S[key];else S[key]=value;render();showChangeFeedback(T2('Could not save the undo. Please try again.','تغییر ذخیره نشد؛ دوباره برگرداندن را بزنید.'));return false}finally{undoBusy=false}
}
function showChangeFeedback(message,canUndo=false){const el=$('#change-feedback');if(!el)return;clearTimeout(feedbackTimer);el.innerHTML=`<span>${bidi(message)}</span>${canUndo?`<button onclick="undoLastChange()">${T2('Undo','برگرداندن')}</button>`:''}`;tr(el);isolateMixed(el);el.hidden=false;feedbackTimer=setTimeout(()=>{el.hidden=true},5000)}
const undoButton=()=>undoRecord()?`<button class="icon-button undo-button" onclick="undoLastChange()" ${sc.busy||tc.busy?'disabled':''} aria-label="${T2('Undo last change','برگرداندن آخرین تغییر')}" title="${esc(undoLabel(undoRecord()))}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 5 4 10l5 5M4 10h10a6 6 0 0 1 0 12"/></svg></button>`:'';

/* ---------- SHIFT CODES ---------- */
// Text format per line: code|label|HH:MM-HH:MM  or  code|label|leave  or  code|label|off
const encCodes=cs=>cs.map(c=>`${c.code}|${c.label}|${c.type==='work'?c.start+'-'+c.end:c.type}`).join('\n');
function decCodes(t){t=nrm(t);return t.split('\n').map(l=>l.split('|').map(x=>x.trim())).filter(a=>a[0]).map(([code,label,v=''])=>{
  const m=v.match(/^(\d{1,2}:\d{2})-(\d{1,2}:\d{2})$/);return m?{code,label,type:'work',start:m[1],end:m[2]}:{code,label,type:v==='off'?'off':'leave'}})}
// Longest-match-first tokenizer: "DEn" -> D,E,n ; "N" never becomes "n" (case-sensitive).
function parse(wp,text){if(!wp?.codes||!text)return null;text=nrm(text).replace(/[–—−]/g,'-');
 const tokens=wp.codes.flatMap(c=>[{token:c.code,c},...(c.aliases||[]).map(token=>({token,c}))]).filter(x=>x.token).sort((a,b)=>b.token.length-a.token.length);
 if(/^[-]+$/.test(text)&&!wp.codes.some(c=>c.code==='-'&&c.type!=='off')){const off=wp.codes.find(c=>c.type==='off');return off?[{...off,code:offCode(wp)}]:null}
 // Explicit hospital definitions take precedence over built-in off aliases.
 if(!tokens.some(x=>x.token===text)&&/^(off|\*)$/i.test(text)){const c=wp.codes.find(c=>c.type==='off');if(c)return[{...c,code:offCode(wp)}]}
 let i=0,out=[];while(i<text.length){const matches=tokens.filter(x=>text.startsWith(x.token,i)),m=matches[0];if(!m)return null;
 if(matches.some(x=>x.token===m.token&&x.c.code!==m.c.code))return null;out.push(m.c);i+=m.token.length}return out.length?out:null}
const canonicalShift=(w,t)=>{const c=parse(w,t);return c?c.every(x=>x.type==='off')?offCode(w):c.map(x=>x.code).join(''):t};
const codeTokens=w=>[...new Set(w.codes.flatMap(c=>[c.code,...(c.aliases||[])]).join('')+'-م')].join('');
const shiftKind=(w,t)=>{const c=parse(w,t);return !c?'unknown':c.every(x=>x.type==='off')?'off':c.every(x=>x.type==='leave')?'leave':c.some(x=>x.code==='N'||x.code==='n')?'night':c.length>1?'combined':c.some(x=>x.code==='E')?'evening':'day'};
const codeStatusLabel=c=>c.type==='off'?'off':c.label==='Sick leave'||c.label==='مرخصی استعلاجی'?T2('Sick leave','استعلاجی'):c.label;
const rosterLabel=h=>(parse(wp(h.wp),h.text)||[]).map(codeStatusLabel).join(' + ')||h.label;
const shiftMark=(w,t)=>`<em class="shift-mark ${shiftKind(w,t)}">${codeHTML(canonicalShift(w,t))}</em>`;
const at=(d,t)=>{const[h,m]=t.split(':');const[y,mo,da]=d.split('-');return new Date(+y,mo-1,+da,+h,+m).getTime()};
function makeSegs(date,codes){return codes.filter(c=>c.type==='work').map(c=>{const s=at(date,c.start);let e=at(date,c.end);if(e<=s)e+=DAY;return{s,e,code:c.code}})}

/* ---------- SCHEDULE / CONFLICT ENGINE ---------- */
const segs=()=>S.shifts.flatMap(h=>h.segs.map(g=>({...g,wp:h.wp,sh:h.id}))).sort((a,b)=>a.s-b.s);
function issues(){const out=[],active=[];let latest=null;for(const g of segs()){
 for(let i=active.length-1;i>=0;i--)if(active[i].e<=g.s)active.splice(i,1);
 // A handover overlap within one workplace is continuous duty, not double booking.
 if(S.cross)for(const a of active)if(a.wp!==g.wp)out.push({t:'o',a,b:g,min:(Math.min(a.e,g.e)-g.s)/6e4});
 if(latest&&g.s>=latest.e&&(g.s-latest.e)/6e4<S.gap&&latest.sh!==g.sh)out.push({t:'g',a:latest,b:g,min:(g.s-latest.e)/6e4});
 if(!latest||g.e>latest.e)latest=g;active.push(g)}return out}
// The Today card follows a continuous combined duty until its final end time.
function displaySegs(){return S.shifts.flatMap(h=>{const sorted=h.segs.map(g=>({...g,wp:h.wp,sh:h.id})).sort((a,b)=>a.s-b.s),out=[];for(const g of sorted){const last=out.at(-1);if(last&&g.s<=last.e){last.e=Math.max(last.e,g.e);last.code=canonicalShift(wp(h.wp),h.text);last.aggregate=true}else out.push({...g})}return out}).sort((a,b)=>a.s-b.s)}
const wp=id=>S.wps.find(w=>w.id===id)||{name:'?',color:'#888'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Attribute-safe JavaScript arguments keep imported identifiers out of executable markup.
const jsArg=v=>esc(JSON.stringify(String(v??'')));
const safeColor=v=>/^#[0-9a-f]{3}(?:[0-9a-f]{3})?$/i.test(String(v))?v:'#888888';
const imageSrc=v=>/^data:image\/(?:jpeg|png|webp|gif);base64,[a-z0-9+/=\s]+$/i.test(String(v))?esc(v):'';
const bidi=(v,dir='auto')=>`<bdi dir="${dir}">${esc(v)}</bdi>`;
const codeHTML=v=>bidi(v,'ltr');
const dur=m=>{m=Math.max(0,Math.round(m));const h=Math.floor(m/60),n=m%60;return S.lang==='fa'?[h?`${h} ساعت`:'',n||!h?`${n} دقیقه`:''].filter(Boolean).join(' و '):[h?`${h} ${h===1?'hour':'hours'}`:'',n||!h?`${n} ${n===1?'minute':'minutes'}`:''].filter(Boolean).join(' ')};
const countdown=m=>{m=Math.max(0,Math.ceil(m));const days=Math.floor(m/1440);return days?`${days} ${S.lang==='fa'?'روز':days===1?'day':'days'}${m%1440?(S.lang==='fa'?' و ':' ')+dur(m%1440):''}`:dur(m)};
const placeColor=id=>S.themePlaces!==false?['var(--ac)','var(--ac-alt)','var(--ac-third)'][Math.max(0,S.wps.findIndex(w=>w.id===id))%3]:safeColor(wp(id).color);
const hm=ms=>{const d=new Date(ms);return S.h24?String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'):d.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})};
const iso=d=>{d=new Date(d);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const loc=()=>S.lang==='fa'?(S.cal==='j'?'fa-IR-u-ca-persian':'fa-IR-u-ca-gregory'):(S.cal==='j'?'en-GB-u-ca-persian':'en-GB');
const weekdayShort=d=>S.lang==='fa'?['یک','دو','سه','چهار','پنج','جمعه','شنبه'][d.getDay()]:d.toLocaleDateString(loc(),{weekday:'short'});
const dateText=value=>{const d=typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)?new Date(value+'T00:00'):new Date(value);const j=S.cal==='j'?jp(d):{d:d.getDate(),m:d.getMonth()+1,y:d.getFullYear()};return `${j.y}/${j.m}/${j.d}`};
const dateHTML=value=>codeHTML(dateText(value));
const dlabel=d=>new Date(d+'T00:00').toLocaleDateString(loc(),{weekday:'short'})+' · '+dateText(d);
const dayLabel=d=>`${new Date(d+'T00:00').toLocaleDateString(loc(),{weekday:'long'})} · ${dateHTML(d)}`;
const timeRange=(a,b)=>`${codeHTML(hm(a)+' – '+hm(b))}${iso(a)!==iso(b)?` <small class="mu">${T2('ends','پایان')} ${dateHTML(b)}</small>`:''}`;
const badge=sh=>{const review=S.shifts.find(h=>h.id===sh)?.review?'<span class="bad g">Needs review</span>':'';const matches=issues().filter(i=>i.a.sh===sh||i.b.sh===sh);return review+['o','g'].map(type=>{const items=matches.filter(i=>i.t===type);if(!items.length)return '';return `<span class="bad ${type}">${type==='o'?'Overlap ':'Gap '}${dur(Math.max(...items.map(i=>i.min)))}${items.length>1?` · ${items.length}`:''}</span>`}).join(' ')};

const segTxt=g=>`${codeHTML(g.code)} ${timeRange(g.s,g.e)}`;

/* ---------- UI ---------- */
const V={};
function go(t){const d=$('#dlg');if(d.open)d.close();suspendInline();if(t==='team'){tc.v='cover';tc.res=null;tc.filter='all';tc.notice=''}tab=t;render();window.scrollTo?.(0,0)}
function render(){suspendInline();const editor=inlineDrafts.get(inlineView());const opened=$('#v').dataset.tab===tab?[...$('#v').querySelectorAll('details[open]')].map(d=>d.dataset.keepOpen||d.querySelector('summary')?.textContent):[];document.documentElement.dataset.ac=S.ac||'fox';document.documentElement.dataset.theme=S.theme==='auto'?'':S.theme;
  $('nav').innerHTML=NAV.slice(0,3).map(([k,i,l])=>`<button aria-current="${k===tab?'page':'false'}" class="${k===tab?'on':''}" onclick="go(${jsArg(k)})"><i>${i}</i>${l}</button>`).join('');$('#v').innerHTML=V[tab]();$('#v').dataset.tab=tab;document.documentElement.lang=S.lang;document.documentElement.dir=S.lang==='fa'?'rtl':'ltr';hdr();tr($('nav'));tr($('#hd'));tr($('#v'));isolateMixed($('#v'));isolateMixed($('#hd'));$('#v').querySelectorAll('details').forEach(d=>{if(opened.includes(d.dataset.keepOpen||d.querySelector('summary')?.textContent))d.open=true});if(editor){inlineEditor=editor;if(editor.shiftId!==undefined)editingShift=editor.shiftId;mountInline(editor)}else inlineEditor=null;draftNotice()}
const autoDir=r=>r.querySelectorAll('input:not([dir]):not([type=file]):not([type=date]):not([type=time]):not([type=color]):not([type=checkbox]),textarea:not([dir])').forEach(i=>i.dir='auto');
const dlg=h=>{suspendInline();$('#dlg').innerHTML=`<button class="dialog-close" onclick="closeDialog()" aria-label="${T2('Close','بستن')}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg></button>`+h;autoDir($('#dlg'));tr($('#dlg'));isolateMixed($('#dlg'));$('#dlg').querySelectorAll('button').forEach(b=>{if(!b.classList.contains('dialog-close')&&b.getAttribute('onclick')?.trim()==='closeDialog()')b.classList.add('cancel-button')});if(!$('#dlg').open)$('#dlg').showModal()};function closeDialog(){dismissInline();const d=$('#dlg');if(d.open)d.close();}

/* Everyday actions stay within the page. A detached node preserves draft fields on re-render. */
let inlineEditor=null;const inlineDrafts=new Map();
const inlineView=()=>tab+'|'+(tab==='team'?tc.v:'');
function suspendInline(){if(inlineEditor){if(inlineEditor.node.querySelector('#fc'))inlineEditor.shiftId=editingShift;inlineEditor.node.remove();inlineDrafts.set(inlineEditor.view,inlineEditor);inlineEditor=null}}
function dismissInline(){inlineEditor?.node.remove();inlineDrafts.delete(inlineView());inlineEditor=null;draftNotice()}
function draftNotice(){document.querySelector('#draft-notice')?.remove();const drafts=[...inlineDrafts.values()].filter(e=>e.view!==inlineView());if(!drafts.length)return;const node=document.createElement('div');node.id='draft-notice';node.className='draft-notice';node.setAttribute('role','status');node.innerHTML=`<span>${T2('Unsaved draft','پیش‌نویس ذخیره نشده')}</span><button class="text-button" onclick="resumeDraft()">${T2('Continue editing','ادامهٔ ویرایش')}</button>`;$('#v').prepend(node)}
function resumeDraft(){const draft=[...inlineDrafts.values()].find(e=>e.view!==inlineView());if(!draft)return;suspendInline();const [dest,view]=draft.view.split('|');tab=dest;if(dest==='team')tc.v=view;render();draft.node.open=true;draft.node.scrollIntoView?.({block:'start'});draft.node.querySelector('summary').focus?.({preventScroll:true})}
function mountInline(editor){let anchor;
 if(typeof editor.anchor==='object'){const a=editor.anchor;anchor=a.type==='colleague'?[...document.querySelectorAll('.colleague-card')].find(n=>n.dataset.mid===a.mid):[...document.querySelectorAll('.swap-option')].find(n=>n.dataset.hid===a.hid&&n.dataset.mid===a.mid&&(!a.date||n.dataset.date===a.date))}
 else anchor=editor.anchor&&$(editor.anchor);
 if(anchor){let closed;while(closed=anchor.parentElement?.closest('details:not([open])'))anchor=closed;anchor.insertAdjacentElement('afterend',editor.node);}else $('#v').prepend(editor.node);
}
