function addSchedule(){if(!S.wps.length)return go('setup');if(!S.shifts.length){resumeSetup();return}showInline(`<h3>${T2('Add schedule','افزودن برنامه')}</h3><button class="p" onclick="closeDialog();go('scan')">${T2('Scan roster photo','اسکن عکس برنامه')}</button><button class="p s" onclick="closeDialog();addShift()">${T2('Enter a shift manually','ثبت دستی شیفت')}</button><button class="text-button" onclick="closeDialog()">${T2('Cancel','لغو')}</button>`)}
