const setupSteps=step=>`<ol class="setup-steps" aria-label="${T2('Setup progress','مراحل شروع')}">${[T2('Workplace','محل کار'),T2('Schedule','برنامه'),T2('Review','بررسی')].map((label,i)=>`<li class="${i+1<=step?'done':''}" ${i+1===step?'aria-current="step"':''}><b>${i+1<step?'✓':i+1}</b><span>${label}</span></li>`).join('')}</ol>`;
