V.setup=()=>`${setupSteps(1)}<section class="c setup-card"><div class="setup-title"><span class="fox-mark"></span><h2>${T2('Let’s set up your schedule','از اینجا شروع کنیم')}</h2></div><p class="mu">${T2('Start with your workplace. Next, we’ll add your roster photo.','نام محل کارتان را بنویسید؛ بعد عکس برنامه را با هم بررسی می‌کنیم.')}</p><label>${T2('Workplace name','نام محل کار')}<input id="setup-workplace" maxlength="100" autocomplete="organization" placeholder="${T2('e.g. hospital or ward','مثلاً نام بیمارستان یا بخش')}"></label><label>${T2('Your name (optional)','نام شما (اختیاری)')}<input id="setup-name" maxlength="100" autocomplete="name" value="${esc(S.myname)}" placeholder="${T2('As written on the roster','همان نامی که در برنامه نوشته شده')}"></label><p class="setup-note">${T2('You can choose your name from the photo, and adjust shift symbols and hours anytime.','می‌توانید نام خود را از عکس انتخاب کنید. معنی علامت‌ها و ساعت شیفت‌ها هم قابل تغییرند.')}</p><button class="p" onclick="completeSetup()">${T2('Continue · Add schedule','ادامه · افزودن برنامه')}</button></section>`;
async function completeSetup(){const name=$('#setup-workplace').value.trim();if(!name){$('#setup-workplace').focus();return alert(T2('What is your workplace called?','نام محل کارتان چیست؟'))}const w={id:'w'+Date.now(),name,color:'#ea8430',codes:decCodes(DEF.map(d=>d.join('|')).join('\n')),combos:[...DEFAULT_COMBOS]};if(!await saveSettings({wps:[...S.wps,w],myname:$('#setup-name').value.trim(),onboarding:{wp:w.id,stage:'scan'}}))return;sc.wp=w.id;sc.name=S.myname;go('scan')}
function dayStatus(date,id=''){const places=id?S.wps.filter(w=>w.id===id):S.wps.filter(w=>w.active!==false);const hs=S.shifts.filter(h=>h.date===date&&(!id||h.wp===id));const unknown=places.some(w=>!hs.some(h=>h.wp===w.id&&!h.review)&&S.rosterDays?.[w.id+'|'+date]!==true)||hs.some(h=>h.review);return{hs,unknown}}
