 const ids=(id?S.wps.filter(w=>w.id===id):S.wps).map(w=>w.id);
 return ids.some(w=>own(S.rosterDays,w+'|'+date))||(S.rosterPeriods||[]).some(p=>ids.includes(p.wp)&&date>=p.start&&date<=p.end)
