function coverageText(){const places=S.wps.filter(w=>w.active!==false),ends=places.map(w=>{const dates=[...S.shifts.filter(h=>h.wp===w.id).map(h=>h.date),...Object.keys(S.rosterDays||{}).filter(k=>k.startsWith(w.id+'|')).map(k=>k.slice(k.lastIndexOf('|')+1))].sort();return dates.at(-1)});if(!ends.length||ends.some(d=>!d))return T2('Complete the roster for each workplace.','برنامهٔ همهٔ محل‌های کار را کامل کنید.');const end=ends.sort()[0];return T2('Saved roster through ','برنامهٔ ثبت‌شده تا ')+dateText(end)}
V.today=()=>{if(!S.wps.length)return`<section class="c welcome-card"><span class="fox-mark welcome-fox" aria-hidden="true"></span><h2>${T2('Hello, welcome to FoxiOra','سلام، به FoxiOra خوش آمدید')}</h2><p class="mu">${T2('Your shifts, your free time, a little more clarity. Let’s start with your workplace and roster.','بیایید شیفت‌هایتان را کنار هم بچینیم و وقت آزاد را راحت‌تر پیدا کنیم. اول محل کار، بعد عکس برنامه.')}</p><button class="p" onclick="go('setup')">${T2('Let’s get started','شروع کنیم')}</button><small>${T2('Your schedule stays on this device.','برنامه‌تان روی همین دستگاه ذخیره می‌شود.')}</small></section>`;
 if(!S.shifts.length)return`${setupSteps(2)}<section class="c welcome-card"><h2>${T2('Your workplace is ready','محل کارتان آماده است')}</h2><p class="mu">${T2('Add a roster photo to see your shifts and free time together.','فقط عکس برنامه مانده؛ اضافه‌اش کنیم تا شیفت‌ها و وقت آزادتان یک‌جا دیده شوند.')}</p><button class="p" onclick="resumeSetup()">${T2('Add my schedule','افزودن برنامهٔ من')}</button><button class="text-button" onclick="addShift()">${T2('Enter shifts manually','ثبت دستی شیفت‌ها')}</button></section>`;
  const now=Date.now(),all=displaySegs(),current=all.filter(g=>g.s<=now&&now<g.e),cur=current[0],next=all.filter(g=>g.s>now),hero=cur||next[0],after=(cur?next:next.slice(1))[0];
  const hv=hero?`<section class="hero"><div class="row"><span class="pill">${cur?T2('ON SHIFT','در حال شیفت'):T2('NEXT SHIFT','شیفت بعدی')}</span><span class="hero-date">${dateHTML(hero.s)}</span></div>
    <div class="hero-main"><div><h2>${bidi(cLabel(hero))}</h2><div class="hero-place"><i style="background:${placeColor(hero.wp)}"></i>${bidi(wp(hero.wp).name)}</div></div><span class="hero-code">${codeHTML(hero.code)}</span></div>
    <div class="hero-time">${timeRange(hero.s,hero.e)}</div><div class="cd"><span>${cur?T2('Time remaining','تا پایان شیفت'):T2('Until your next shift','تا شیفت بعدی')}</span><strong>${countdown(((cur?cur.e:hero.s)-now)/6e4)}</strong></div>
    ${cur?`<div class="prog"><i style="width:${Math.min(100,Math.round((now-cur.s)/(cur.e-cur.s)*100))}%"></i></div>`:''}</section>`:`<div class="c empty-state"><b>${T2('No upcoming work shift is saved','شیفت کاری بعدی هنوز ثبت نشده')}</b><p class="mu">${bidi(coverageText())}<br>${T2('Add your next roster to keep planning.','برای ادامهٔ برنامه‌ریزی، برنامهٔ بعدی را اضافه کنید.')}</p></div>`;
  const today=new Date(),strip=Array.from({length:7},(_,i)=>{const d=new Date(today.getFullYear(),today.getMonth(),today.getDate()+i),ds=iso(d),hs=S.shifts.filter(h=>h.date===ds),hol=holidayInfo(d);return `<button class="dchip${i?'':' t'}${isWeekend(d)||hol.length?' holiday':''}" onclick="sel=${jsArg(ds)};vm='month';cm=mfirst(new Date('${ds}T00:00'));go('agenda')"><span title="${d.toLocaleDateString(loc(),{weekday:'long'})}">${weekdayShort(d)}</span><b>${S.cal==='j'?jp(d).d:d.getDate()}</b><em>${hs.map(h=>codeHTML(h.text)).join(' ')}${dayStatus(ds).unknown?`<span class="unknown-mark" title="${T2('Roster incomplete','برنامه ناقص است')}">${T2('?','؟')}</span>`:!hs.length?`<span class="unknown-mark">${T2('Blank','خالی')}</span>`:''}</em></button>`}).join('');
  const weekEnd=new Date(today.getFullYear(),today.getMonth(),today.getDate()+7).getTime(),start=at(iso(now),'00:00'),week=all.filter(g=>g.s<weekEnd&&g.e>start),weekIssues=issues().filter(i=>i.b.s<weekEnd&&i.a.e>start),count=new Set(week.map(g=>g.sh)).size;
  return hv+`<div class="section-heading"><h1>${T2('THE NEXT 7 DAYS','هفت روز پیش‌رو')}</h1><button class="text-button" onclick="go('agenda')">${T2('Calendar','تقویم')}</button></div><div class="week-strip">${strip}</div><small class="coverage-note">${bidi(coverageText())} · ${T2('? means unknown','؟ یعنی نامشخص')}</small>`+freePreview()+
    (new Set(current.map(g=>g.wp)).size>1?`<div class="c alert-card">${T2('More than one shift is active now. Check the overlapping times.','هم‌زمان بیش از یک شیفت فعال است. زمان شیفت‌ها را بررسی کنید.')}</div>`:'')+
    weekIssues.slice(0,3).map(i=>`<div class="c alert-card"><b>${i.t==='o'?T2('Shift overlap','تداخل شیفت‌ها'):T2('Short break','فاصلهٔ کوتاه بین شیفت‌ها')} · ${dur(i.min)}</b><div class="mu">${bidi(wp(i.a.wp).name)} ${segTxt(i.a)}<br>${bidi(wp(i.b.wp).name)} ${segTxt(i.b)}</div></div>`).join('')};

