let wpDraft=[];
function groupedCodes(w){const off=w.codes.filter(c=>c.type==='off'),rest=w.codes.filter(c=>c.type!=='off').map(c=>({...c,aliases:[...(c.aliases||[])]}));if(off.length){const c=off.find(c=>c.code==='-')||off[0];rest.push({...c,code:offCode(w),aliases:[...new Set(off.flatMap(x=>[x.code,...(x.aliases||[])]).concat(['OFF','*','-']))].filter(x=>x!==offCode(w)&&!rest.some(c=>c.code===x||(c.aliases||[]).includes(x)))})}return rest}
function codeEditorRows(){return wpDraft.map((c,i)=>`<details class="code-editor" data-index="${i}"><summary><bdi dir="ltr">${esc(c.code||'?')}</bdi><span>${esc(codeStatusLabel(c))}</span><small>${c.type==='off'?T2('Off','off'):c.type==='leave'?T2('Leave','مرخصی'):esc(c.start+' – '+c.end)}</small></summary><div class="code-fields"><label>${T2('Symbol in your roster','علامت در برنامه')}<input class="code-value" dir="auto" value="${esc(c.code)}" autocapitalize="off"></label><label>${T2('Meaning','معنی')}<input class="code-label" value="${esc(codeStatusLabel(c))}"></label><label>${T2('Kind','نوع')}<select class="code-type" onchange="this.closest('.code-editor').querySelector('.code-times').hidden=this.value!=='work'">${['work','off','leave'].map(t=>`<option value="${t}" ${c.type===t?'selected':''}>${t==='work'?T2('Work','شیفت'):t==='off'?T2('Off','off'):T2('Leave','مرخصی')}</option>`).join('')}</select></label><label>${T2('Other symbols with this meaning','علامت‌های هم‌معنی')}<input class="code-alias" dir="auto" placeholder="${T2('Separate with commas','با ویرگول جدا کنید')}" value="${esc((c.aliases||[]).join(', '))}"></label><div class="code-times" ${c.type!=='work'?'hidden':''}><label>${T2('Start','شروع')}<input class="code-start" type="time" value="${esc(c.start||'07:30')}"></label><label>${T2('End','پایان')}<input class="code-end" type="time" value="${esc(c.end==='24:00'?'00:00':c.end||'14:30')}"></label></div></div><button class="text-button danger-text" onclick="removeCode(${i})">${T2('Remove symbol','حذف علامت')}</button></details>`).join('')}
function collectCodes(){return [...$('#code-rows').querySelectorAll('.code-editor')].map(r=>({code:nrm(r.querySelector('.code-value').value.trim()),label:r.querySelector('.code-label').value.trim(),type:r.querySelector('.code-type').value,start:r.querySelector('.code-start').value,end:r.querySelector('.code-end').value,aliases:nrm(r.querySelector('.code-alias').value).split(/[,،]/).map(x=>x.trim()).filter(Boolean)}))}
function appendCode(){wpDraft=collectCodes();wpDraft.push({code:'',label:'',type:'work',start:'07:30',end:'14:30',aliases:[]});$('#code-rows').innerHTML=codeEditorRows();$('#code-rows').lastElementChild.open=true;$('#code-rows').lastElementChild.querySelector('input').focus()}
function removeCode(i){wpDraft=collectCodes();wpDraft.splice(i,1);$('#code-rows').innerHTML=codeEditorRows()}
function editWp(id,showCodes=false){const w=S.wps.find(x=>x.id===id)||{name:'',color:'#bd541b',codes:decCodes(DEF.map(d=>d.join('|')).join('\n'))};wpDraft=groupedCodes(w);
 dlg(`<h3>${id?T2('Edit workplace','ویرایش محل کار'):T2('New workplace','محل کار جدید')}</h3><label>${T2('Name','نام')}<input id="wn" value="${esc(w.name)}" placeholder="${T2('Hospital / ward','بیمارستان / بخش')}"></label><details class="symbol-setup" ${showCodes||!id?'open':''}><summary>${T2('Teach roster symbols & hours','تعریف علامت‌ها و ساعت شیفت‌ها')}</summary><p class="mu">${T2('Tap a symbol to set its meaning and hours. Off aliases (−, OFF, *) share one meaning. Changes apply to new entries; saved shift times stay unchanged.','برای تغییر معنی یا ساعت، روی علامت بزنید. تغییر ساعت‌ها برای شیفت‌های جدید اعمال می‌شود.')}</p><label>${T2('Empty cells in photos','خانه‌های خالی در عکس برنامه')}<select id="wblank"><option value="unknown" ${!w.blankMeansOff?'selected':''}>${T2('Unknown','نامشخص')}</option><option value="off" ${w.blankMeansOff?'selected':''}>off</option></select></label><div id="code-rows">${codeEditorRows()}</div><button class="p s" onclick="appendCode()">${T2('+ Add symbol','+ افزودن علامت')}</button><label class="setup-combos">${T2('Allowed combined shifts','شیفت‌های ترکیبی مجاز')}<input id="wcm" dir="ltr" value="${esc((w.combos??DEFAULT_COMBOS).join(', '))}" placeholder="DE, En"></label><small class="mu">${T2('For example DE: morning + evening, including their handover overlap.','مثلاً DE یعنی صبح + عصر.')}</small></details><details><summary>${T2('Other workplace options','گزینه‌های دیگر محل کار')}</summary><label class="setting-row"><span><b>${T2('Include in free time and trips','در محاسبهٔ وقت آزاد و سفر لحاظ شود')}</b></span><span class="switch-control"><input id="wa" type="checkbox" role="switch" ${w.active!==false?'checked':''}><span class="switch-track" aria-hidden="true"></span></span></label><label class="setting-row"><span><b>${T2('Off after a night shift','off بعد از شیفت شب')}</b></span><span class="switch-control"><input id="wno" type="checkbox" role="switch" ${w.nightOff!==false?'checked':''}><span class="switch-track" aria-hidden="true"></span></span></label><label>${T2('Staff names (optional)','فهرست نام همکاران (اختیاری)')}<textarea id="wstaff" rows="3" placeholder="${T2('One name per line','هر نام در یک خط')}">${esc((w.staffNames||[]).join('\n'))}</textarea></label><p class="mu">${T2('A staff list helps suggest names when a scan is unclear.','اگر فهرست همکاران را دارید، اینجا وارد کنید تا نام‌های ناخوانا راحت‌تر پیدا شوند.')}</p><label>${T2('Workplace color','رنگ محل کار')}<input id="wc" type="color" value="${esc(w.color||'#bd541b')}"></label></details><div class="dialog-actions"><button class="p" onclick="saveWp(${jsArg(id||'')})">Save</button><button class="p s" onclick="closeDialog()">${T2('Cancel','لغو')}</button></div>${id?`<details class="danger-zone"><summary>${T2('Remove workplace','حذف محل کار')}</summary><button class="p danger-button" onclick="delWp(${jsArg(id)})">Delete</button></details>`:''}`)}
async function saveWp(id){const n=$('#wn').value.trim();if(!n)return alert(T2('Enter a workplace name.','نام محل کار را وارد کنید.'));const codes=collectCodes();
 const tokens=new Map();for(const c of codes){if(!c.code||!c.label||/[\s,،|]/.test(c.code)||(c.type==='work'&&(!/^\d{2}:\d{2}$/.test(c.start)||!/^\d{2}:\d{2}$/.test(c.end))))return alert(T2('Check symbol names, meanings and hours.','علامت‌ها، معنی و ساعت‌ها را بررسی کنید.'));for(const token of [c.code,...c.aliases]){if(tokens.has(token)&&tokens.get(token)!==c.code)return alert(T2('A symbol has more than one meaning: ','این علامت چند معنی دارد: ')+token);tokens.set(token,c.code)}}
 if(!codes.length)return alert(T2('Add at least one symbol.','حداقل یک علامت تعریف کنید.'));const o={name:n,color:$('#wc').value,active:$('#wa').checked,nightOff:$('#wno').checked,blankMeansOff:$('#wblank').value==='off',staffNames:$('#wstaff').value.split(/\n/).map(x=>x.trim()).filter(Boolean).slice(0,500),codes};o.combos=nrm($('#wcm').value).split(/[,\s،]+/).filter(Boolean);
 if(o.combos.some(x=>{const c=parse(o,x);return !c||c.length<2||c.some(y=>y.type!=='work')}))return alert(T2('Combined shifts must contain two or more working symbols.','شیفت ترکیبی باید شامل حداقل دو علامت کاری باشد.'));
 const change=beginChange('Workplace','محل کار',['wps','shifts','mates']);if(id)Object.assign(S.wps.find(w=>w.id===id),o);else S.wps.push({id:'w'+Date.now(),...o});normalizeSavedOff();if(!await commitChange(change))return;closeDialog();render()}
function normalizeSavedOff(){for(const w of S.wps){for(const c of w.codes)if(c.type==='off')c.label='off';for(const h of S.shifts.filter(x=>x.wp===w.id)){const c=parse(w,h.text);if(!h.segs.length&&c?.every(x=>x.type==='off'))h.text=offCode(w)}for(const m of mates(w.id))for(const [d,t] of Object.entries(m.cells)){const c=parse(w,t);if(c?.every(x=>x.type==='off'))m.cells[d]=offCode(w)}}}
async function delWp(id){if(!confirm(T2('Remove this workplace and its schedules?','این محل کار و برنامه‌هایش حذف شوند؟')))return;const change=beginChange('Workplace removal','حذف محل کار',['wps','shifts','mates','rosterDays','rosterPeriods']);S.rosterPeriods=(S.rosterPeriods||[]).filter(p=>p.wp!==id);S.wps=S.wps.filter(w=>w.id!==id);S.shifts=S.shifts.filter(h=>h.wp!==id);S.mates=S.mates.filter(m=>m.wp!==id);for(const k of Object.keys(S.rosterDays||{}))if(k.startsWith(id+'|'))delete S.rosterDays[k];if(!await commitChange(change))return;closeDialog();if(!S.wps.length)tab='today';render()}

