function scanEvidence(c){return{img:c.img||'',feature:c.feature||null,raw:c.raw||'',blank:!!c.blank}}
function scanMonthLength(){const b=S.cal==='j'?fromJ(sc.y,sc.m,1):new Date(sc.y,sc.m-1,1);return calendarDays(mfirst(b)).filter(Boolean).length}
function scanPreview(source,x0,y0,x1,y1,height=64){const cv=document.createElement('canvas'),w=Math.max(1,x1-x0),h=Math.max(1,y1-y0);cv.width=Math.max(1,Math.round(height*w/h));cv.height=height;const x=cv.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,cv.width,cv.height);x.drawImage(source,x0,y0,w,h,0,0,cv.width,cv.height);return cv.toDataURL('image/jpeg',.8)}
function confirmScanName(value){sc.name=value.trim();sc.nameConfirmed=true}
function scanPendingIndices(){const w=wp(sc.wp);return(sc.cells||[]).map((c,i)=>cState(w,c)!=='ok'?i:-1).filter(i=>i>=0)}
function selectScanCell(i){if(!sc.cells?.[i])return;sc.reviewIndex=i;render();document.querySelector('.scan-focus')?.scrollIntoView?.({block:'nearest'})}
