function scanPendingV(){const pending=scanPendingIndices();return pending.length?`<section class="scan-pending" aria-label="${T2('Shifts to check','شیفت‌های نیازمند بررسی')}"><b>${T2('Start with these dates','این روزها را بررسی کنیم')}</b><p class="mu">${T2('Choose a date, then its correct shift.','روز را انتخاب کنید و علامت درست شیفت را بزنید.')}</p><div class="pending-dates">${pending.map(i=>`<button class="pending-date ${sc.reviewIndex===i?'on':''}" aria-pressed="${sc.reviewIndex===i}" onclick="selectScanCell(${i})">${T2('Day ','روز ')}${sc.cells[i].day} · <bdi>${esc(sc.cells[i].text||'?')}</bdi></button>`).join('')}</div></section>`:`<p class="review-complete" role="status">${T2('All clear. Tap any day if you want to change it.','همهٔ شیفت‌ها مشخص‌اند. برای تغییر هر روز، روی آن بزنید.')}</p>`}
function reviewV(){const w=wp(sc.wp),st=sc.cells.map(c=>cState(w,c)),pending=st.filter(x=>x!=='ok').length;sc.reviewIndex=Math.max(0,Math.min(sc.reviewIndex||0,sc.cells.length-1));const i=sc.reviewIndex,c=sc.cells[i],row=sc.rows[sc.ri];
 return `${isSettingUp()?setupSteps(3):''}<section class="c scan-review"><div class="review-heading"><h2>${T2('Your schedule, at a glance','برنامه‌تان در یک نگاه')}</h2><span class="mu">${pending?T2(pending+' to check',pending+' خانه برای بررسی'):T2('Ready to save','آمادهٔ ثبت')}</span></div><details class="scan-name-details"><summary>${bidi(sc.name||T2('Your name','نام شما'))} · ${T2('Edit','ویرایش')}</summary><label class="scan-name">${T2('Your name','نام شما')}<input value="${esc(sc.name)}" aria-label="${T2('Your name','نام شما')}" onchange="confirmScanName(this.value)"></label></details>${sc.guess?`<p class="scan-notice">${T2('Let’s check the dates once for this page.','تاریخ‌های این صفحه را یک‌بار با هم بررسی کنیم.')} <button class="p s" onclick="openDateCheck(${row.pi||0})">${T2('Check dates','بررسی تاریخ‌ها')}</button></p>`:''}${scanPendingV()}${c?`<div class="scan-focus"><div class="scan-focus-head"><b>${T2('Edit shift · ','ویرایش شیفت · ')}${dateHTML(c.date)}</b><img src="${imageSrc(c.img)}" alt="${T2('Shift from photo','شیفت در عکس')}"></div><div class="pending-navigation"><button class="p s" ${pending?'':'disabled'} onclick="moveScanPending(-1)">${T2('Previous unclear','نامشخص قبلی')}</button><span role="status">${st[i]!=='ok'?T2('Needs checking','نیاز به بررسی'):T2('Clear','مشخص')}</span><button class="p s" ${pending?'':'disabled'} onclick="moveScanPending(1)">${T2('Next unclear','نامشخص بعدی')}</button></div><div class="keys">${presetCodes(w).map(p=>`<button class="k${c.text===p.code?' on':''}" aria-pressed="${c.text===p.code}" onclick="setCell(${i},${jsArg(p.code)})">${esc(p.code)}</button>`).join('')}<button class="k unknown-key" onclick="setCell(${i},'')">${T2('Unknown','نامشخص')}</button></div><details><summary>${T2('Other symbol','علامت دیگر')}</summary><input dir="ltr" value="${esc(c.text)}" aria-label="${T2('Shift symbol','علامت شیفت')}" onchange="setCell(${i},nrm(this.value.trim()))"></details></div>`:''}<div class="scan-month-grid">${sc.cells.map((cell,j)=>`<button class="scan-day ${st[j]!=='ok'?'pending':''} ${i===j?'selected':''}" aria-pressed="${i===j}" aria-label="${esc(dateText(cell.date)+' '+(cell.text||T2('Unknown','نامشخص')))}" onclick="selectScanCell(${j})"><small>${cell.day}</small><bdi>${esc(cell.text||'?')}</bdi>${st[j]!=='ok'?'<span class="review-dot">•</span>':''}</button>`).join('')}</div><div class="scan-tools"><button class="text-button" onclick="sc.cells=null;sc.pick=true;render()">${T2('Choose another row','انتخاب ردیف دیگر')}</button><button class="text-button" onclick="openDateCheck(${row.pi||0})">${T2('Dates','تاریخ‌ها')}</button><button class="text-button" onclick="startAlignment(${row.pi||0})">${T2('Straighten photo','صاف کردن عکس')}</button><button class="text-button" onclick="editWp(${jsArg(w.id)},true)">${T2('Symbol meanings','معنی علامت‌ها')}</button></div>${sc.cells.some(x=>x.blank)?blankChoiceV(w):''}</section><div class="sticky review-actions"><button class="p" onclick="doImport(sc.importMates===true)">${T2('Save schedule','ثبت برنامه')}</button><label class="review-mates"><input type="checkbox" ${sc.importMates?'checked':''} onchange="sc.importMates=this.checked">${T2('Also read colleagues','برنامهٔ همکاران هم خوانده شود')}</label></div>`}
function blankChoiceV(w){return `<label class="blank-choice">${T2('In this workplace, an empty cell means…','در برنامهٔ این محل کار، خانهٔ خالی یعنی…')}<select aria-label="${T2('Meaning of empty cells','معنی خانهٔ خالی')}" onchange="setBlankMeaning(this.value==='off')"><option value="unknown" ${!w.blankMeansOff?'selected':''}>${T2('Unknown · check it','نامشخص · نیاز به بررسی')}</option><option value="off" ${w.blankMeansOff?'selected':''}>off</option></select></label>`}
async function setBlankMeaning(off){const w=wp(sc.wp);if(off&&!offCode(w))return alert(T2('Define an off symbol first.','ابتدا علامت off را تعریف کنید.'));const change=beginChange('Empty-cell meaning','معنی خانهٔ خالی',['wps']);w.blankMeansOff=!!off;if(!await commitChange(change))return;for(const c of sc.cells||[])if(c.blank&&!c.confirmed)Object.assign(c,off?{text:offCode(w),c:90,uncertain:false}:{text:'',c:0,uncertain:true});render()}
function openDateCheck(pi){const p=sc.pages?.[pi];if(!p)return;sc.dateCheck={pi,col:Math.max(0,p.vl.slice(0,-1).findIndex((_,i)=>p.dayAt(i)===1)),dr:p.dr,count:scanMonthLength()};render()}
function dateCheckV(){const d=sc.dateCheck,p=sc.pages[d.pi],H=p.hl,V=p.vl;return `<section class="c"><h2>${T2('Match the dates to the photo','تاریخ‌ها را با عکس تطبیق دهید')}</h2><p class="mu">${T2('Tap the column for day 1. The labels below show the dates that will be saved.','ستون روز ۱ را انتخاب کنید. شماره‌های زیر، تاریخ‌هایی هستند که ثبت می‌شوند.')}</p>${sc.pages.length>1?`<p>${T2('Page','صفحه')} ${d.pi+1}</p>`:''}<div class="date-check-fields"><label>${T2('Dates increase toward','روزها به کدام سمت جلو می‌روند؟')}<select onchange="sc.dateCheck.dr=+this.value;render()"><option value="-1" ${d.dr<0?'selected':''}>${T2('Left','چپ')}</option><option value="1" ${d.dr>0?'selected':''}>${T2('Right','راست')}</option></select></label><label>${T2('Number of days','تعداد روزها')}<input type="number" min="1" max="31" value="${d.count}" onchange="sc.dateCheck.count=Math.max(1,Math.min(31,+this.value||1));render()"></label></div><div class="date-columns" dir="ltr">${V.slice(0,-1).map((_,i)=>{const day=1+(i-d.col)*d.dr;return `<button class="date-column ${i===d.col?'selected':''}" aria-pressed="${i===d.col}" onclick="sc.dateCheck.col=${i};render()"><img src="${scanPreview(p.cv,V[i],Math.max(0,H[0]-(H[1]-H[0])*.7),V[i+1],H[1])}" alt="${T2('Date column','ستون تاریخ')} ${i+1}"><b>${day>=1&&day<=d.count?day:'—'}</b></button>`}).join('')}</div><p class="mu">${T2('If columns or rows are misplaced, straighten the photo first.','اگر ستون‌ها یا ردیف‌ها درست جدا نشده‌اند، اول عکس را صاف کنید.')}</p><div class="dialog-actions"><button class="p" onclick="applyDateCheck()">${T2('Dates match · continue','تاریخ‌ها درست‌اند · ادامه')}</button><button class="p s" onclick="sc.dateCheck=null;sc.continueReadAll=false;sc.pick=!!sc.rows?.length;render()">${T2('Cancel','لغو')}</button></div><button class="text-button" onclick="startAlignment(${d.pi})">${T2('Straighten photo','صاف کردن عکس')}</button></section>`}
async function applyDateCheck(){const d=sc.dateCheck,p=sc.pages[d.pi],end=d.col+(d.count-1)*d.dr;if(end<0||end>=p.vl.length-1||[d.col,end].some(i=>i===p.nameCol)||p.nameCol>Math.min(d.col,end)&&p.nameCol<Math.max(d.col,end))return alert(T2('These dates reach outside the date columns. Check day 1 and the direction.','تاریخ‌ها از ستون‌های روزها خارج می‌شوند. ستون روز ۱ و جهت را بررسی کنید.'));const mapping=i=>{const day=1+(i-d.col)*d.dr;return day>=1&&day<=d.count?day:0},changed=p.vl.slice(0,-1).some((_,i)=>{const old=p.dayAt(i);return(old>=1&&old<=d.count?old:0)!==mapping(i)});p.dayAt=mapping;p.dr=d.dr;p.guess=false;p.datesConfirmed=true;sc.dateCheck=null;usePage(d.pi);if(sc.continueReadAll){sc.continueReadAll=false;return readAll()}if(sc.cells&&sc.rows[sc.ri]?.pi===d.pi&&changed){sc.busy=true;render();return readCells(sc.ri)}render()}
// Manual perspective correction stays on the device; the original scan is retained.
function startAlignment(pi){const p=sc.pages?.[pi];if(!p)return;sc.dateCheck=null;sc.align={pi,cv:p.source||p.cv,points:[]};render()}
function alignmentV(){const a=sc.align,labels=[T2('top left','بالا چپ'),T2('top right','بالا راست'),T2('bottom right','پایین راست'),T2('bottom left','پایین چپ')];return `<section class="c"><h2>${T2('Straighten the table','جدول را صاف کنیم')}</h2><p>${a.points.length<4?T2('Tap the '+labels[a.points.length]+' corner of the full table (including names and dates).','گوشهٔ '+labels[a.points.length]+' جدول کامل را بزنید؛ نام‌ها و تاریخ‌ها هم داخل آن باشند.'):T2('All four corners selected.','هر چهار گوشه انتخاب شد.')}</p><div class="alignment-photo" onclick="alignmentPoint(event)"><img draggable="false" src="${a.cv.toDataURL('image/jpeg',.85)}" alt="${T2('Roster photo: select four table corners','عکس برنامه: چهار گوشهٔ جدول را انتخاب کنید')}">${a.points.map((p,i)=>`<span style="left:${p.x/a.cv.width*100}%;top:${p.y/a.cv.height*100}%">${i+1}</span>`).join('')}</div><div class="scan-tools"><button class="p s" onclick="sc.align.cv=turn(sc.align.cv,90);sc.align.points=[];render()">${T2('Rotate 90°','چرخش ۹۰°')}</button><button class="p s" ${a.points.length?'':'disabled'} onclick="sc.align.points.pop();render()">${T2('Undo point','برگرداندن نقطه')}</button></div><div class="dialog-actions"><button class="p" ${a.points.length===4?'':'disabled'} onclick="applyAlignment()">${T2('Straighten & read again','صاف کردن و خواندن دوباره')}</button><button class="p s" onclick="sc.align=null;render()">${T2('Cancel','لغو')}</button></div><p class="mu">${T2('A flat, clear original photo still gives the best result.','عکس اصلی، صاف و واضح بهترین نتیجه را می‌دهد.')}</p></section>`}
function alignmentPoint(event){const a=sc.align;if(!a||a.points.length===4)return;const r=event.currentTarget.getBoundingClientRect();a.points.push({x:Math.max(0,Math.min(a.cv.width,(event.clientX-r.left)/r.width*a.cv.width)),y:Math.max(0,Math.min(a.cv.height,(event.clientY-r.top)/r.height*a.cv.height))});render()}
function straightenTable(source,p){if(p.length!==4)throw Error('Select four corners.');const cross=(a,b,c)=>(b.x-a.x)*(c.y-b.y)-(b.y-a.y)*(c.x-b.x);if(p.some((a,i)=>cross(a,p[(i+1)%4],p[(i+2)%4])<=0))throw Error(T2('Select the corners in the shown order.','گوشه‌ها را به ترتیب گفته‌شده انتخاب کنید.'));const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),w=Math.round(Math.max(dist(p[0],p[1]),dist(p[3],p[2]))),h=Math.round(Math.max(dist(p[0],p[3]),dist(p[1],p[2])));if(w<80||h<80)throw Error(T2('Include the whole table.','تمام جدول را داخل کادر قرار دهید.'));const out=document.createElement('canvas');out.width=w+32;out.height=h+32;const ctx=out.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,out.width,out.height);const input=source.getContext('2d').getImageData(0,0,source.width,source.height),im=ctx.getImageData(16,16,w,h),[a,b,c,d]=p,dx1=b.x-c.x,dx2=d.x-c.x,dx3=a.x-b.x+c.x-d.x,dy1=b.y-c.y,dy2=d.y-c.y,dy3=a.y-b.y+c.y-d.y,det=dx1*dy2-dx2*dy1,g=(dx3*dy2-dx2*dy3)/det,k=(dx1*dy3-dx3*dy1)/det;
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){const u=x/(w-1),v=y/(h-1),z=g*u+k*v+1,X=((b.x-a.x+g*b.x)*u+(d.x-a.x+k*d.x)*v+a.x)/z,Y=((b.y-a.y+g*b.y)*u+(d.y-a.y+k*d.y)*v+a.y)/z,ix=Math.max(0,Math.min(source.width-2,Math.floor(X))),iy=Math.max(0,Math.min(source.height-2,Math.floor(Y))),fx=Math.max(0,Math.min(1,X-ix)),fy=Math.max(0,Math.min(1,Y-iy)),q=(y*w+x)*4;for(let ch=0;ch<3;ch++){const n=(iy*source.width+ix)*4+ch;im.data[q+ch]=input.data[n]*(1-fx)*(1-fy)+input.data[n+4]*fx*(1-fy)+input.data[n+source.width*4]*(1-fx)*fy+input.data[n+source.width*4+4]*fx*fy}im.data[q+3]=255}ctx.putImageData(im,16,16);return out}
async function applyAlignment(){const a=sc.align;let cv;try{cv=straightenTable(a.cv,a.points)}catch(e){return alert(e.message)}const previous=sc.pages[a.pi],length=sc.pages.length;sc.align=null;sc.cells=null;sc.pick=false;sc.busy=true;sc.msg='';render();try{await readPage(cv);const updated=sc.pages.pop();updated.source=previous.source||previous.cv;sc.pages[a.pi]=updated;sc.rows=sc.pages.flatMap((p,pi)=>p.rows.map(r=>({...r,pi,page:pi+1})));sc.pick=true}catch(e){sc.pages.length=length;sc.msg=e.message;sc.pick=true}finally{sc.busy=false;render()}}
let scanReview={wp:'',selected:new Set()};
function pendingScans(w){const days=new Set(calendarDays(mfirst(roster.cm||cm)).filter(Boolean).map(iso)),items=[];for(const h of S.shifts.filter(h=>h.wp===w.id&&h.review&&days.has(h.date)))items.push({key:'self|'+h.id,self:true,id:h.id,date:h.date,text:h.text,name:S.myname||T2('You','شما'),scan:h.scan});for(const m of mates(w.id))for(const date of [...new Set(m.uns||[])].filter(d=>days.has(d)))items.push({key:m.id+'|'+date,id:m.id,date,text:m.cells[date]||'',name:m.name,scan:m.scan?.[date]});return items.sort((a,b)=>a.name.localeCompare(b.name)||a.date.localeCompare(b.date))}
function openScanReview(id){roster.wp=id;roster.review=true;scanReview={wp:id,selected:new Set()};if(tab!=='roster')openRoster(id);else render()}
function editPendingScan(key){scanReview.selected=new Set([key]);render();document.querySelector('.scan-batch-actions')?.scrollIntoView?.({block:'nearest'})}
function toggleScanReview(key){scanReview.selected.has(key)?scanReview.selected.delete(key):scanReview.selected.add(key);render()}
function selectSimilarScan(key){const items=pendingScans(wp(roster.wp)),seed=items.find(x=>x.key===key);if(!seed?.scan?.feature)return;scanReview.selected=new Set(items.filter(x=>x.scan?.feature&&featureDistance(seed.scan.feature,x.scan.feature)<.12).map(x=>x.key));render()}
function savedScanReviewV(w){const items=pendingScans(w),keys=new Set(items.map(x=>x.key));scanReview.selected=new Set([...scanReview.selected].filter(k=>keys.has(k)));return `<section class="c saved-scan-review"><div class="review-heading"><h2>${T2('Check unclear shifts','بررسی شیفت‌های نامشخص')}</h2><button class="text-button" onclick="roster.review=false;render()">${T2('Back to roster','برگشت به برنامه')}</button></div><p class="mu">${T2('Select matching photos, then choose their shift symbol below. Clear shifts are already usable.','عکس‌های هم‌شکل را انتخاب کنید و علامت درستشان را پایین بزنید. شیفت‌های واضح همین حالا قابل استفاده‌اند.')}</p><p aria-live="polite">${items.length?T2(items.length+' to check · '+scanReview.selected.size+' selected',items.length+' خانه برای بررسی · '+scanReview.selected.size+' انتخاب‌شده'):T2('All checked for this month.','بررسی این ماه تمام شد.')}</p>${items.length?`<div class="scan-batch-actions"><b>${T2('Selected cells mean…','خانه‌های انتخاب‌شده یعنی…')}</b><div class="keys">${presetCodes(w).map(c=>`<button class="k" ${scanReview.selected.size?'':'disabled'} onclick="saveScanGroup(${jsArg(c.code)})">${esc(c.code)}</button>`).join('')}</div><button class="text-button" onclick="scanReview.selected.clear();render()">${T2('Clear selection','پاک کردن انتخاب‌ها')}</button></div>`:''}<div class="saved-scan-cards">${items.map(x=>`<div class="saved-scan-card ${scanReview.selected.has(x.key)?'selected':''}"><label><input type="checkbox" ${scanReview.selected.has(x.key)?'checked':''} onchange="toggleScanReview(${jsArg(x.key)})"><span>${bidi(x.name)}<small>${dateHTML(x.date)}</small></span>${x.scan?.img?`<img src="${imageSrc(x.scan.img)}" alt="${T2('Shift from photo','شیفت در عکس')}">`:`<bdi>${esc(x.text||'?')}</bdi>`}</label><button class="text-button" onclick="editPendingScan(${jsArg(x.key)})">${T2('Edit shift','ویرایش شیفت')}</button>${x.scan?.feature?`<button class="text-button" onclick="selectSimilarScan(${jsArg(x.key)})">${T2('Select similar photos','انتخاب عکس‌های مشابه')}</button>`:''}</div>`).join('')}</div></section>`}
async function saveScanGroup(code){const w=wp(roster.wp),cs=parse(w,code);if(!cs||!scanReview.selected.size)return;const items=pendingScans(w).filter(x=>scanReview.selected.has(x.key)),change=beginChange('Scan corrections','اصلاحات اسکن',['shifts','mates','rosterDays','ocrMemory']);for(const x of items){if(x.scan?.feature)rememberExample('glyphs',w.id,x.scan.feature,x.scan.raw,code,x.scan.img);if(x.self){const h=S.shifts.find(h=>h.id===x.id);Object.assign(h,{text:code,label:cs.map(c=>c.label).join(' + '),segs:makeSegs(x.date,cs),review:false});delete h.scan;S.rosterDays=S.rosterDays||{};S.rosterDays[w.id+'|'+x.date]=true}else{const m=S.mates.find(m=>m.id===x.id);m.cells[x.date]=code;m.uns=(m.uns||[]).filter(d=>d!==x.date);if(m.scan)delete m.scan[x.date]}}if(!await commitChange(change))return;tc.res=null;scanReview.selected.clear();render()}

function setScanPurpose(only){if($('#sw'))readForm();sc.colleaguesOnly=!!only;render()}
function addColleaguePages(id){sc.wp=id;sc.name=S.myname||'';sc.colleaguesOnly=true;sc.cells=null;sc.pick=false;sc.dateCheck=null;sc.align=null;sc.pages=[];sc.ri=-1;sc.msg='';go('scan')}
function importColleaguePages(){sc.colleaguesOnly=true;sc.ri=-1;sc.pick=false;sc.cells=null;sc.busy=false;return readAll()}
/* ===== v11 Team: colleagues, cover finder, compare ===== */
const T2=(en,fa)=>S.lang==='fa'?fa:en;
const mates=id=>(S.mates||[]).filter(m=>m.wp===id);
let tc={peopleSearch:'',v:'cover',wp:'',dates:[],res:null,mate:'',busy:false,month:'',mode:'month',cm:null,filter:'all',notice:''};
const openCover=()=>{tc.v='cover';tc.res=null;go('team')};
const curWp=()=>S.wps.find(x=>x.id===tc.wp)||S.wps.find(w=>mates(w.id).length)||S.wps[0];
const isWork=(w,t)=>{const c=t&&parse(w,t);return !!c&&c.some(x=>x.type==='work')};
const isOff=(w,t)=>{const c=t&&parse(w,t);return !!c&&c.every(x=>x.type==='off')};
const mateSegs=(w,m)=>Object.entries(m.cells).flatMap(([d,t])=>{const c=parse(w,t);return c?makeSegs(d,c):[]}).sort((a,b)=>a.s-b.s);
/* Colleague preferences: explicit limits win; observed patterns are suggestions unless enabled. */
function colleaguePattern(w,m,date){
 const valid=Object.entries(m.cells||{}).filter(([d,t])=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&iso(new Date(d+'T00:00'))===d&&!(m.uns||[]).includes(d)&&!!parse(w,t)).sort(([a],[b])=>a.localeCompare(b));
 const target=date||valid.at(-1)?.[0]||iso(Date.now()),from=rosterDate(target,-62),to=rosterDate(target,31),rows=valid.filter(([d])=>d>=from&&d<=to),duties=rows.filter(([,t])=>isWork(w,t));
 if(rows.length<20||duties.length<8)return null;
 const codes=[...new Set(duties.map(([,t])=>canonicalShift(w,t)))];
 if(codes.length!==1||parse(w,codes[0]).filter(c=>c.type==='work').length!==1)return null;
 return{codes,reviewed:rows.length,work: duties.length,from:rows[0][0],to:rows.at(-1)[0]};
}
function dutyHours(segs){const sorted=segs.map(g=>({...g})).sort((a,b)=>a.s-b.s),merged=[];for(const g of sorted){const last=merged.at(-1);if(last&&g.s<=last.e)last.e=Math.max(last.e,g.e);else merged.push(g)}return merged.reduce((n,g)=>n+g.e-g.s,0)/3600000}
function colleagueLimit(w,m,text,date,segs=makeSegs(date,parse(w,text)||[])){
 const rules=m.swapRules||{},code=canonicalShift(w,text),parts=parse(w,code)||[];
 if(rules.awayFrom&&rules.awayUntil&&date>=rules.awayFrom&&date<=rules.awayUntil)return T2('Unavailable during the selected dates.','در این بازه برای تعویض در دسترس نیست.');
 if(Array.isArray(rules.weekdays)&&!rules.weekdays.includes(new Date(date+'T00:00').getDay()))return T2('This weekday is outside their availability.','این روز هفته در زمان‌های قابل‌قبول این همکار نیست.');
 if(rules.excluded)return T2('Excluded from shift suggestions.','از پیشنهادهای تعویض کنار گذاشته شده است.');
 if(Array.isArray(rules.allowed)&&!rules.allowed.map(t=>canonicalShift(w,t)).includes(code))return T2('This shift is outside their accepted shifts.','این شیفت در انتخاب‌های این همکار نیست.');
 if(rules.noCombined&&(parts.filter(c=>c.type==='work').length>1||(w.combos??DEFAULT_COMBOS).includes(code)))return T2('Combined duties are disabled for this colleague.','شیفت ترکیبی برای این همکار انتخاب نشده است.');
 if(Number(rules.maxHours)>0&&dutyHours(segs)>Number(rules.maxHours)+1e-7)return T2(`Exceeds their ${rules.maxHours}-hour limit.`,`از سقف ${rules.maxHours} ساعت این همکار بیشتر است.`);
 if(w.autoPatterns===true&&!rules.ignorePattern&&!Array.isArray(rules.allowed)){const pattern=colleaguePattern(w,m,date);if(pattern&&!pattern.codes.includes(code))return T2('Outside the observed roster pattern.','با الگوی ثبت‌شدهٔ این همکار سازگار نیست.');}
 return '';
}
async function updateColleagueRules(id,patch){const m=S.mates.find(m=>m.id===id);if(!m)return;const change=beginChange('Colleague preferences','تنظیمات همکار',['mates']);m.swapRules={...m.swapRules,...patch};if(!await commitChange(change))return;render()}
function effectiveAllowedShifts(w,m){const r=m.swapRules||{};return Array.isArray(r.allowed)?r.allowed.map(t=>canonicalShift(w,t)):w.autoPatterns&&!r.ignorePattern?colleaguePattern(w,m)?.codes||null:null}
function allowAllShifts(id){return updateColleagueRules(id,{allowed:null,ignorePattern:true})}
function toggleAllowedShift(id,code){const m=S.mates.find(m=>m.id===id);if(!m)return;const w=wp(m.wp),allowed=effectiveAllowedShifts(w,m)||preferenceCodes(w,m).map(c=>c.code);return updateColleagueRules(id,{allowed:allowed.includes(code)?allowed.filter(t=>t!==code):[...allowed,code]})}
function applyColleaguePattern(id){const m=S.mates.find(m=>m.id===id);if(!m)return;const pattern=colleaguePattern(wp(m.wp),m);if(pattern)updateColleagueRules(id,{allowed:pattern.codes,ignorePattern:false})}
async function setPatternFiltering(id,enabled){const w=S.wps.find(w=>w.id===id);if(!w)return;const change=beginChange('Pattern filtering','فیلتر الگوی برنامه',['wps']);w.autoPatterns=!!enabled;if(!await commitChange(change))return;render()}
function preferenceCodes(w,m){const map=new Map(presetCodes(w).filter(c=>isWork(w,c.code)).map(c=>[canonicalShift(w,c.code),c]));for(const t of m.swapRules?.allowed||[])if(!map.has(t))map.set(t,{code:t,label:T2('Saved choice','انتخاب ثبت‌شده')});return[...map.values()]}
function colleagueRuleLabel(w,m){const r=m.swapRules||{},pattern=w.autoPatterns&&!r.ignorePattern&&!Array.isArray(r.allowed)?colleaguePattern(w,m):null;if(r.excluded)return T2('Excluded','کنار گذاشته شده');const allowed=Array.isArray(r.allowed)?r.allowed:pattern?.codes;return [allowed?allowed.length?allowed.join(' / '):T2('No shifts selected','شیفتی انتخاب نشده'):T2('All shifts','همهٔ شیفت‌ها'),r.noCombined&&T2('No combined duty','بدون شیفت ترکیبی'),r.maxHours>0&&T2(`Up to ${r.maxHours} hours`,`تا ${r.maxHours} ساعت`)].filter(Boolean).join(' · ')}
function colleaguePreset(id,key){const m=S.mates.find(m=>m.id===id);if(!m)return;const base={excluded:false,allowed:null,noCombined:false,maxHours:0,ignorePattern:true};if(key==='excluded')base.excluded=true;if(key==='simple')base.noCombined=true;if(key==='D'||key==='E')base.allowed=[canonicalShift(wp(m.wp),key)];return updateColleagueRules(id,base)}
function presetSelected(m,key){const r=m.swapRules||{};if(key==='excluded')return !!r.excluded;if(r.excluded)return false;if(key==='D'||key==='E')return r.allowed?.length===1&&canonicalShift(wp(m.wp),r.allowed[0])===canonicalShift(wp(m.wp),key);return !Array.isArray(r.allowed)&&!(r.maxHours>0)&&(key==='simple'?r.noCombined:!r.noCombined)&&!!r.ignorePattern}
function toggleColleagueWeekday(id,day){const m=S.mates.find(m=>m.id===id);if(!m)return;const days=m.swapRules?.weekdays??[0,1,2,3,4,5,6],next=days.includes(day)?days.filter(d=>d!==day):[...days,day];return updateColleagueRules(id,{weekdays:next.length===7?null:next})}
function setColleagueAway(id,clear=false){const from=clear?'':dGet('away-from-'+id),until=clear?'':dGet('away-until-'+id);if(!clear&&(!from||!until||until<from))return alert(T2('Choose a valid start and end date.','تاریخ شروع و پایان بازه را درست وارد کنید.'));return updateColleagueRules(id,{awayFrom:from,awayUntil:until})}
function colleagueAvailability(m){const r=m.swapRules||{},id=esc(JSON.stringify(m.id));return `<details class="availability-settings" data-keep-open="availability-${esc(m.id)}"><summary>${T2('Availability & temporary limits','روزهای قابل‌قبول و محدودیت موقت')}</summary><p class="mu">${T2('Weekdays available for new duties','روزهای قابل‌قبول برای شیفت جدید')}</p><div class="weekday-choices">${Array.from({length:7},(_,i)=>(i+S.fdow)%7).map(day=>`<button aria-pressed="${!Array.isArray(r.weekdays)||r.weekdays.includes(day)}" onclick="toggleColleagueWeekday(${id},${day})">${new Date(2024,0,7+day).toLocaleDateString(loc(),{weekday:'short'})}</button>`).join('')}</div><p class="mu">${T2('Do not suggest during this period','در این بازه پیشنهاد نشود')}</p><div class="shift-fields"><label>${T2('From','از')}${dField('away-from-'+m.id,r.awayFrom||iso(Date.now()))}</label><label>${T2('Until','تا')}${dField('away-until-'+m.id,r.awayUntil||iso(Date.now()))}</label></div><div class="dialog-actions"><button class="p s" onclick="setColleagueAway(${id})">${T2('Apply dates','ثبت بازه')}</button><button class="text-button" onclick="setColleagueAway(${id},true)">${T2('Clear period','پاک کردن بازه')}</button></div>${r.awayFrom&&r.awayUntil?`<small>${dateHTML(r.awayFrom)} – ${dateHTML(r.awayUntil)}</small>`:''}</details>`}
function colleagueIdentity(m){const candidates=mates(m.wp).filter(x=>x.id!==m.id);if(!candidates.length)return '';return `<details class="identity-settings" data-keep-open="identity-${esc(m.id)}"><summary>${T2('Same person in a previous scan?','همان همکار در برنامهٔ قبلی؟')}</summary><p class="mu">${T2('Link only if both names refer to the same person. Their preferences stay with them.','اگر نام این همکار در اسکن قبلی متفاوت خوانده شده، آن را به همان شخص پیوند دهید.')}</p><select id="identity-${esc(m.id)}" aria-label="${T2('Existing colleague','همکار ثبت‌شده')}"><option value="">${T2('Choose an existing colleague','همکار قبلی را انتخاب کنید')}</option>${candidates.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select><button class="p s" onclick="linkColleague(${esc(JSON.stringify(m.id))},document.getElementById(${jsArg('identity-'+m.id)}).value)">${T2('Link rosters','پیوند برنامه‌ها')}</button></details>`}
async function linkColleague(sourceId,targetId){const source=S.mates.find(m=>m.id===sourceId),target=S.mates.find(m=>m.id===targetId);if(!source||!target||source===target||source.wp!==target.wp)return;const change=beginChange('Colleague link','پیوند همکار',['mates']);target.aliases=[...new Set([...(target.aliases||[]),...(source.aliases||[]),source.name,source.rawName].filter(Boolean))];Object.assign(target.cells,source.cells);target.scan={...target.scan,...source.scan};target.uns=[...new Set([...(target.uns||[]).filter(d=>!(d in source.cells)),...(source.uns||[])])];for(const key of ['img','rawName','nameFeature'])if(source[key])target[key]=source[key];S.mates=S.mates.filter(m=>m.id!==sourceId);tc.res=null;if(!await commitChange(change))return;render();openColleagues(targetId)}
function matchingColleague(id,name){const matches=mates(id).filter(m=>[m.name,...(m.aliases||[])].some(alias=>nn(alias)===nn(name)));return name&&matches.length===1?matches[0]:null}
function colleagueCard(w,m){const r=m.swapRules||{},id=esc(JSON.stringify(m.id)),pattern=colleaguePattern(w,m),allowed=effectiveAllowedShifts(w,m);const toggle=(key,label,checked,inverted=false)=>`<label class="setting-row"><span><b>${label}</b></span><span class="switch-control"><input type="checkbox" role="switch" aria-label="${esc(label)}" ${checked?'checked':''} onchange="updateColleagueRules(${id},{${key}:${inverted?'!':''}this.checked})"><span class="switch-track" aria-hidden="true"></span></span></label>`;
 return `<details class="colleague-card c" data-mid="${esc(m.id)}" data-keep-open="colleague-${esc(m.id)}"><summary><span><b>${bidi(m.name||'?')}</b><small>${bidi(colleagueRuleLabel(w,m))}</small></span><span class="colleague-status ${r.excluded?'excluded':''}">${r.excluded?T2('Excluded','کنار گذاشته'):T2('Settings','تنظیم')}</span></summary><div class="colleague-body"><div class="colleague-presets" role="group" aria-label="${T2('Quick preferences','انتخاب سریع')}">${[['flexible',T2('Flexible','منعطف')],['D',T2('D only','فقط D')],['E',T2('E only','فقط E')],['simple',T2('No combined','بدون ترکیبی')],['excluded',T2('Exclude','کنار گذاشته')]].filter(([key])=>!['D','E'].includes(key)||isWork(w,key)).map(([key,label])=>`<button aria-pressed="${presetSelected(m,key)}" onclick="colleaguePreset(${id},${jsArg(key)})">${label}</button>`).join('')}</div>${pattern&&!Array.isArray(r.allowed)?`<div class="observed-pattern"><p><span>${T2('Observed pattern','الگوی برنامه')}</span> <b>${codeHTML(pattern.codes.join(' / '))}</b></p><details class="pattern-evidence" data-keep-open="pattern-${esc(m.id)}"><summary>${T2('View evidence','دیدن جزئیات الگو')}</summary><small>${T2(`${pattern.work} duties among ${pattern.reviewed} reviewed dates.`,`${pattern.reviewed} روز بررسی‌شده؛ ${pattern.work} شیفت ${pattern.codes.join(' / ')}.`)} ${dateHTML(pattern.from)} – ${dateHTML(pattern.to)}</small></details><button class="text-button" onclick="applyColleaguePattern(${id})">${T2('Use these shifts','فقط همین شیفت‌ها')}</button></div>`:''}
 <details class="colleague-advanced" data-keep-open="advanced-${esc(m.id)}"><summary>${T2('More preferences','تنظیمات بیشتر')}</summary>${toggle('excluded',T2('Include in suggestions','در پیشنهادها باشد'),!r.excluded,true)}
 <details class="accepted-shifts" data-keep-open="accepted-${esc(m.id)}"><summary>${T2('Accepted shifts','شیفت‌های قابل‌قبول')}</summary><div class="preference-actions"><button class="text-button" onclick="allowAllShifts(${id})">${T2('All','همه')}</button><button class="text-button" onclick="updateColleagueRules(${id},{allowed:[]})">${T2('Clear selections','پاک کردن انتخاب‌ها')}</button></div><div class="preference-keys" role="group" aria-label="${T2('Accepted shifts','شیفت‌های قابل‌قبول')}">${preferenceCodes(w,m).map(c=>`<button aria-pressed="${!Array.isArray(allowed)||allowed.includes(c.code)}" onclick="toggleAllowedShift(${id},${esc(JSON.stringify(c.code))})">${codeHTML(c.code)}</button>`).join('')}</div></details>
 ${toggle('noCombined',T2('No combined duties','بدون شیفت ترکیبی'),!!r.noCombined)}
 <label class="setting-field"><span>${T2('Maximum duty length','حداکثر مدت شیفت')}</span><select aria-label="${T2('Maximum duty length','حداکثر مدت شیفت')}" onchange="updateColleagueRules(${id},{maxHours:+this.value})">${[0,8,12,16,24,...(![0,8,12,16,24].includes(+r.maxHours)&&+r.maxHours>0?[+r.maxHours]:[])].map(h=>`<option value="${h}" ${(+r.maxHours||0)===h?'selected':''}>${h?T2(`${h} hours`,`${h} ساعت`):T2('No limit','بدون محدودیت')}</option>`).join('')}</select></label>
 ${w.autoPatterns?toggle('ignorePattern',T2('Ignore automatic pattern','نادیده گرفتن الگوی خودکار'),!!r.ignorePattern):''}
 ${colleagueAvailability(m)}${colleagueIdentity(m)}</details><div class="colleague-actions"><button class="text-button" onclick="renMate(${id})">${T2('Correct name','اصلاح نام')}</button><button class="text-button danger-text" onclick="delMate(${id})">${T2('Remove','حذف')}</button></div></div></details>`;
}
function colleaguesV(w){const ms=mates(w.id).filter(m=>!tc.peopleSearch||nn(m.name).includes(nn(tc.peopleSearch)));return `<input class="colleague-search" aria-label="${T2('Search colleagues','جستجوی همکاران')}" placeholder="${T2('Search colleagues','جستجوی همکاران')}" value="${esc(tc.peopleSearch||'')}" oninput="filterColleagues(this.value)">`+ `<section class="c pattern-settings"><label class="setting-row"><span><b>${T2('Automatically filter clear patterns','فیلتر خودکار الگوهای روشن')}</b><small>${T2('Manual preferences take priority. Turn off to review patterns yourself.','تنظیمات هر همکار مقدم است؛ با خاموش بودن، الگوها فقط پیشنهاد می‌شوند.')}</small></span><span class="switch-control"><input type="checkbox" role="switch" aria-label="${T2('Automatically filter clear patterns','فیلتر خودکار الگوهای روشن')}" ${w.autoPatterns?'checked':''} onchange="setPatternFiltering(${esc(JSON.stringify(w.id))},this.checked)"><span class="switch-track" aria-hidden="true"></span></span></label></section>`+(ms.length?ms.map(m=>colleagueCard(w,m)).join(''):`<p class="mu">${T2('No matching colleague.','همکاری با این نام پیدا نشد.')}</p>`)+`<details class="settings-group colleague-comparison" data-keep-open="colleague-comparison"><summary>${T2('Compare schedules','مقایسهٔ برنامه‌ها')}</summary>${cmpV(w)}</details>`}
function filterColleagues(value){tc.peopleSearch=value;render();const el=$('.colleague-search');el?.focus();el?.setSelectionRange(value.length,value.length)}
function openColleagues(id){tc.peopleSearch='';tc.v='cmp';tab='team';render();if(id){const card=[...document.querySelectorAll('.colleague-card')].find(n=>n.dataset.mid===id);if(card){card.open=true;card.scrollIntoView?.({block:'nearest',behavior:'instant'})}}else window.scrollTo?.(0,0)}

// Facts about a colleague around a shift (their previous/next shift and the gap) — information only, no advice.
function facts(w,m,h){const ss=mateSegs(w,m),s0=Math.min(...h.segs.map(g=>g.s)),e0=Math.max(...h.segs.map(g=>g.e)),p=[...ss].reverse().find(g=>g.e<=s0),n=ss.find(g=>g.s>=e0);return{p:p&&{c:p.code,g:(s0-p.e)/6e4},n:n&&{c:n.code,g:(n.s-e0)/6e4}}}
const factTxt=f=>[f.p&&`${T2('before','قبلش')}: ${codeHTML(f.p.c)} <span class="${f.p.g<S.gap?'tight':''}">(${dur(f.p.g)})</span>`,f.n&&`${T2('after','بعدش')}: ${codeHTML(f.n.c)} <span class="${f.n.g<S.gap?'tight':''}">(${dur(f.n.g)})</span>`].filter(Boolean).join(' · ');
// For each shift I want to hand over: colleagues who are off that day, or whose own shift + mine is an allowed combination.
function combinedCode(w,a,b){const ca=canonicalShift(w,a),cb=canonicalShift(w,b);return (w.combos??DEFAULT_COMBOS).find(c=>{const p=parse(w,c);return p?.every(x=>x.type==='work')&&(canonicalShift(w,c)===ca+cb||canonicalShift(w,c)===cb+ca)})||''}
// Local date arithmetic also handles month/year boundaries and timezone changes.
const rosterDate=(date,offset)=>{const d=new Date(date+'T00:00');return iso(new Date(d.getFullYear(),d.getMonth(),d.getDate()+offset))};
function personalRoster(w){const cells={},saved={},uns=[];for(const h of S.shifts.filter(h=>h.wp===w.id)){if(cells[h.date]!==undefined)uns.push(h.date);cells[h.date]=h.text;saved[h.date]=h.segs;if(h.review)uns.push(h.date)}return{cells,saved,uns,self:true}}
function nightDuty(w,date,text,segs=makeSegs(date,parse(w,text)||[])){return !!parse(w,text)?.some(c=>c.type==='work'&&c.code==='N')||segs.some(g=>iso(g.e)!==date&&new Date(g.e).getHours()+new Date(g.e).getMinutes()/60>0)}
// Validate the resulting roster, not the two transfers in isolation. Unrelated old issues do not block a change.
function checkRosterChange(w,person,changes,strict=false){
 const cells={...person.cells},uns=new Set(person.uns||[]),changed=Object.keys(changes);for(const [date,c] of Object.entries(changes)){cells[date]=c.text;uns.delete(date)}
 const known=date=>!uns.has(date)&&!!parse(w,cells[date]);
 const duty=date=>changes[date]?.segs??person.saved?.[date]??makeSegs(date,parse(w,cells[date])||[]);
 const result=(kind,reason,date)=>({kind,reason,date});
 const other=person.self?S.shifts.filter(h=>h.wp!==w.id).flatMap(h=>h.segs.map(g=>({...g,date:h.date,wp:h.wp}))):[];
 for(const date of changed){const c=changes[date];if(!isWork(w,c.text))continue;const prev=rosterDate(date,-1),next=rosterDate(date,1);
  if(uns.has(prev))return result('unknown','previous',prev);
  if(person.self&&S.shifts.some(h=>h.wp!==w.id&&h.review&&h.date>=prev&&h.date<=(nightDuty(w,date,c.text,c.segs)?next:date)))return result('unknown','scan',date);
  if(w.nightOff!==false){
   if((strict||nightDuty(w,date,c.text,c.segs))&&!known(prev))return result('unknown','previous',prev);
   if(known(prev)&&nightDuty(w,prev,cells[prev],duty(prev)))return result('blocked','nightOff',date);
   if(person.self&&S.shifts.some(h=>h.wp!==w.id&&h.date===prev&&wp(h.wp).nightOff!==false&&nightDuty(wp(h.wp),prev,h.text,h.segs)))return result('blocked','nightOff',date);
   if(nightDuty(w,date,c.text,c.segs)){
    if(!known(next))return result('unknown','next',next);
    if(!isOff(w,cells[next])||other.some(g=>g.date===next))return result('blocked','nightOff',next);
   }
  }
  const ownOthers=Object.keys(cells).filter(d=>d!==date).flatMap(d=>duty(d)),others=[...ownOthers,...other];
  if(others.some(g=>c.segs.some(p=>g.s<p.e&&p.s<g.e)))return result('blocked','overlap',date);
  if(person.self&&S.events.some(e=>c.segs.some(p=>e.s<p.e&&p.s<e.e)))return result('blocked','event',date);
  const starts=Math.min(...c.segs.map(g=>g.s)),ends=Math.max(...c.segs.map(g=>g.e));
  if([...uns].some(d=>d>=iso(starts)&&d<=iso(ends)))return result('unknown','scan',date);
  if(strict&&others.some(g=>(g.e<=starts&&starts-g.e<S.gap*6e4)||(g.s>=ends&&g.s-ends<S.gap*6e4)))return result('blocked','rest',date);
 }
 return result('ok','',null);
}
function reciprocalSwaps(w,h,m){if(colleagueLimit(w,m,h.text,h.date,h.segs))return{swaps:[],pending:[]};const mine=personalRoster(w),off=offCode(w),swaps=[],pending=[];if(!off||h.review||mine.uns.includes(h.date)||!isOff(w,m.cells[h.date])||(m.uns||[]).includes(h.date))return{swaps,pending};
 for(const date of Object.keys(m.cells).sort()){
  // One-for-one, same-code exchanges keep the choice understandable and do not invent combined duty.
  if(date===h.date||date<iso(Date.now())||(date<rosterDate(h.date,-31)||date>rosterDate(h.date,31))||!isWork(w,m.cells[date])||canonicalShift(w,m.cells[date])!==canonicalShift(w,h.text)||!isOff(w,mine.cells[date]))continue;
  if(mine.uns.includes(date)||(m.uns||[]).includes(date)){pending.push({m,date,reason:'scan'});continue}
  const ownChanges={[h.date]:{text:off,segs:[]},[date]:{text:canonicalShift(w,m.cells[date]),segs:makeSegs(date,parse(w,m.cells[date]))}},mateChanges={[h.date]:{text:h.text,segs:h.segs},[date]:{text:off,segs:[]}};
  const a=checkRosterChange(w,mine,ownChanges,true),b=checkRosterChange(w,m,mateChanges,true),bad=a.kind!=='ok'?a:b;
  if(bad.kind==='ok')swaps.push({m,date,give:h.text,take:canonicalShift(w,m.cells[date]),ownChanges,mateChanges,nightChecked:w.nightOff!==false});
  else if(bad.kind==='unknown')pending.push({m,date:bad.date,reason:bad.reason});
 }
 return{swaps,pending};
}
function coverCalc(w=curWp(),ids=tc.dates){if(!w)return{rows:[],all:[]};const ms=mates(w.id),rows=[];
 for(const id of ids){const h=S.shifts.find(x=>x.id===id);if(!h||h.wp!==w.id||!h.segs.length)continue;const row={h,free:[],ext:[],swap:[],unk:[],blocked:[],pending:[]};
 for(const m of ms){if(m.swapRules?.excluded){row.blocked.push({m,reason:'preference',detail:T2('Excluded from shift suggestions.','از پیشنهادهای تعویض کنار گذاشته شده است.')});continue}const t=m.cells[h.date]||'',cs=parse(w,t);if(h.review||!cs||(m.uns||[]).includes(h.date)){row.unk.push({m,reason:'scan',date:h.date});continue}
  const exchange=reciprocalSwaps(w,h,m);row.swap.push(...exchange.swaps);row.pending.push(...exchange.pending);
  if(cs.some(c=>c.type==='leave'))continue;
  const off=cs.every(c=>c.type==='off'),combo=off?'':combinedCode(w,t,h.text);if(!off&&!combo)continue;
  const proposed=off?h.segs:makeSegs(h.date,parse(w,combo)),a=Math.min(...proposed.map(g=>g.s)),b=Math.max(...proposed.map(g=>g.e));
  const limit=colleagueLimit(w,m,off?h.text:combo,h.date,proposed);if(limit){row.blocked.push({m,reason:'preference',detail:limit});continue}
  const check=checkRosterChange(w,m,{[h.date]:{text:off?h.text:combo,segs:proposed}});
  if(check.kind==='unknown'){row.unk.push({m,reason:check.reason,date:check.date});continue}if(check.kind==='blocked'){row.blocked.push({m,reason:check.reason,date:check.date});continue}
  const others=Object.entries(m.cells).filter(([d])=>d!==h.date).flatMap(([d,t])=>makeSegs(d,parse(w,t)||[])).sort((x,y)=>x.s-y.s),p=[...others].reverse().find(g=>g.e<=a),n=others.find(g=>g.s>=b),f={p:p&&{c:p.code,g:(a-p.e)/6e4},n:n&&{c:n.code,g:(n.s-b)/6e4}};
  const x={m,f,u:false,current:t,nightChecked:w.nightOff!==false&&nightDuty(w,h.date,off?h.text:combo,proposed)};if(off)row.free.push(x);else row.ext.push({...x,combo});
 }
 row.swap.sort((a,b)=>Math.abs(at(a.date,'12:00')-at(h.date,'12:00'))-Math.abs(at(b.date,'12:00')-at(h.date,'12:00'))||a.m.name.localeCompare(b.m.name));rows.push(row)}
 const all=ms.filter(m=>rows.length&&rows.every(r=>r.free.some(x=>x.m.id===m.id)||r.ext.some(x=>x.m.id===m.id))&&checkRosterChange(w,m,Object.fromEntries(rows.map(r=>{const ext=r.ext.find(x=>x.m.id===m.id),text=ext?.combo||r.h.text;return[r.h.date,{text,segs:ext?makeSegs(r.h.date,parse(w,text)):r.h.segs}]}))).kind==='ok');
 return{rows,all};
}
const swapReason=x=>x.reason==='preference'?x.detail||T2('Colleague preferences','تنظیمات همکار'):({nightOff:T2('A day off is needed after the night shift.','استراحت پس از شیفت شب کافی نیست.'),previous:T2('The previous day needs roster data or review.','برنامهٔ روز قبل نیاز به ثبت یا بررسی دارد.'),next:T2('The day after the night shift needs data or review.','روز بعد از شیفت شب نیاز به ثبت یا بررسی دارد.'),scan:T2('This date needs scan review.','این تاریخ نیاز به بررسی برنامه دارد.'),overlap:T2('The proposed shift overlaps another duty.','شیفت پیشنهادی با شیفت دیگری هم‌زمان است.'),event:T2('The return shift overlaps your personal plan.','شیفت برگشتی با برنامهٔ شخصی شما هم‌زمان است.'),rest:T2('The break is shorter than your setting.','فاصلهٔ استراحت از تنظیم شما کوتاه‌تر است.')}[x.reason]||'');
function findExchange(hid,mid,date){const h=S.shifts.find(h=>h.id===hid),w=h&&wp(h.wp),m=S.mates.find(m=>m.id===mid&&m.wp===h?.wp);return h&&m?reciprocalSwaps(w,h,m).swaps.find(x=>x.date===date):null}
function exchangePreview(hid,mid,date){const x=findExchange(hid,mid,date);if(!x)return alert(T2('The roster changed. Find options again.','برنامه تغییر کرده است؛ گزینه‌ها را دوباره بررسی کنید.'));const h=S.shifts.find(h=>h.id===hid),w=wp(h.wp),mine=personalRoster(w),dates=[...new Set([rosterDate(h.date,-1),h.date,rosterDate(h.date,1),rosterDate(date,-1),date,rosterDate(date,1)])].sort();
 const row=(label,cells,changes)=>`<tr><th scope="row">${label}</th>${dates.map(d=>`<td class="${own(changes,d)?'changed-shift':''}">${shiftMark(w,changes[d]?.text??cells[d]??'?')}</td>`).join('')}</tr>`;
 showInline(`<h3>${T2('Exchange preview','پیش‌نمایش تعویض')}</h3><div class="exchange-summary"><p><span>${T2('Your schedule','برنامهٔ شما')}</span><b>${codeHTML(x.take)} · ${dateHTML(date)}</b></p><p><span>${T2('Colleague’s schedule','برنامهٔ همکار')}</span><b>${codeHTML(x.give)} · ${dateHTML(h.date)}</b></p></div><div class="exchange-table-scroll" tabindex="0"><table class="exchange-table"><caption>${T2('Schedules after the change','برنامه پس از تغییر')}</caption><thead><tr><th>${T2('Name','نام')}</th>${dates.map(d=>`<th scope="col" title="${esc(dateText(d))}" aria-label="${esc(dateText(d))}">${codeHTML(dateText(d).split('/').slice(1).join('/'))}</th>`).join('')}</tr></thead><tbody>${row(T2('You','شما'),mine.cells,x.ownChanges)}${row(bidi(x.m.name),x.m.cells,x.mateChanges)}</tbody></table></div><p class="mu">${T2('Save once you have agreed. This updates your two dates and their saved roster on this device.','پس از هماهنگی با همکارتان، تعویض را ثبت کنید.')}</p><div class="dialog-actions"><button class="p" onclick="saveExchange(${jsArg(hid)},${jsArg(mid)},${jsArg(date)})">${T2('Agreed · Save exchange','توافق کردیم · ثبت تعویض')}</button><button class="p s" onclick="closeDialog()">${T2('Cancel','لغو')}</button></div>`,{hid,mid,date})
}
async function saveExchange(hid,mid,date){const x=findExchange(hid,mid,date);if(!x)return alert(T2('This exchange is no longer available. Check the roster again.','این تعویض دیگر قابل انجام نیست؛ برنامه را دوباره بررسی کنید.'));const change=beginChange('Shift exchange','تعویض شیفت',['shifts','mates','rosterDays','swapHistory']);const h=S.shifts.find(h=>h.id===hid),w=wp(h.wp),before={own:S.shifts.filter(s=>s.wp===w.id&&[h.date,date].includes(s.date)).map(s=>({...s,segs:s.segs.map(g=>({...g}))})),mate:Object.fromEntries([h.date,date].map(d=>[d,x.m.cells[d]]))};
 S.rosterDays=S.rosterDays||{};for(const [d,c] of Object.entries(x.ownChanges)){const existing=S.shifts.find(s=>s.wp===w.id&&s.date===d),codes=parse(w,c.text);Object.assign(existing,{text:c.text,segs:c.segs,label:codes.map(c=>c.label).join(' + '),review:false});S.rosterDays[w.id+'|'+d]=true}
 for(const [d,c] of Object.entries(x.mateChanges))x.m.cells[d]=c.text;x.m.uns=(x.m.uns||[]).filter(d=>d!==h.date&&d!==date);
 const id='swap'+Date.now();S.swapHistory=S.swapHistory||[];S.swapHistory.push({id,wp:w.id,mate:x.m.id,dates:[h.date,date],at:Date.now(),before,after:{own:Object.fromEntries(Object.entries(x.ownChanges).map(([d,c])=>[d,c.text])),mate:Object.fromEntries(Object.entries(x.mateChanges).map(([d,c])=>[d,c.text]))}});
 S.swapHistory=S.swapHistory.slice(-50);if(!await commitChange(change))return;closeDialog();tc.notice=T2('Exchange saved for you and ','تعویض برای شما و ')+x.m.name;tc.dates=[];tc.res=null;tab='team';render();window.scrollTo?.(0,0);
}

const togD=id=>{tc.dates=tc.dates.includes(id)?tc.dates.filter(x=>x!==id):[...tc.dates,id];tc.res=null;render()};
const coverGo=()=>{tc.notice='';tc.filter='all';tc.res=coverCalc();render();window.scrollTo?.(0,0)};
function coverRequest(hid,mid){const h=S.shifts.find(x=>x.id===hid),m=S.mates.find(x=>x.id===mid),row=h&&coverCalc(wp(h.wp),[hid]).rows[0],x=row&&[...row.free,...row.ext].find(x=>x.m.id===mid);if(!h||!m||!x)return alert(T2('Find options again; the roster changed.','برنامه تغییر کرده؛ پیشنهادها را دوباره پیدا کنید.'));const text=T2(`Hi ${m.name}, could you take my ${h.text} shift on ${dateText(h.date)}?${x.combo?` Your ${x.current} would become ${x.combo}.`:''} Let me know if it works for you.`,`سلام ${m.name}، می‌توانی شیفت ${h.text} من در ${dateText(h.date)} را بگیری؟${x.combo?` شیفت ${x.current} تو به ${x.combo} تبدیل می‌شود.`:''} اگر برایت مناسب است، هماهنگ کنیم.`);showInline(`<h3>${T2('Request draft','درخواست تعویض')}</h3><p class="mu">${T2('Copy and send it yourself when you’re ready.','متن را کپی کنید و برای همکارتان بفرستید.')}</p><textarea id="request-draft" rows="5" dir="auto">${esc(text)}</textarea><div class="dialog-actions"><button class="p" onclick="copyCoverRequest()">${T2('Copy text','کپی متن')}</button><button class="p s" onclick="closeDialog()">${T2('Close','بستن')}</button></div><p id="request-status" role="status" class="mu"></p>`,{hid,mid})}
async function copyCoverRequest(){const input=$('#request-draft');try{if(!navigator.clipboard?.writeText)throw Error('No clipboard');await navigator.clipboard.writeText(input.value);$('#request-status').textContent=T2('Copied. Ready when you are.','کپی شد؛ هر وقت آماده بودید، بفرستید.')}catch{input.focus();input.select?.();$('#request-status').textContent=T2('Select the text and copy it.','متن را انتخاب و کپی کنید.')}}
function renMate(id){const m=S.mates.find(x=>x.id===id);if(!m)return;
  showInline(`<h3>${T2('Correct colleague name','اصلاح نام همکار')}</h3>${m.img?`<img class="name-preview" src="${imageSrc(m.img)}" alt="${T2('Name from the roster','نام در تصویر برنامه')}">`:''}<label for="mate-name" class="mu">${T2('Correct name','نام صحیح')}</label><input id="mate-name" dir="auto" value="${esc(m.name)}"><p class="mu">${T2('This correction will help recognize the same name in future scans on this device.','نام درست را وارد کنید؛ برای اسکن بعدی به خاطر می‌سپاریم.')}</p><button class="p" onclick="saveMateName(${jsArg(id)})">Save</button><button class="p s" style="margin-top:8px" onclick="closeDialog()">${T2('Cancel','لغو')}</button>`,tab==='team'&&tc.v==='cmp'?{type:'colleague',mid:id}:'.roster-range')}
async function saveMateName(id){const m=S.mates.find(x=>x.id===id),name=$('#mate-name').value.trim();if(!m||!name)return;const change=beginChange('Colleague name','نام همکار',['mates','ocrMemory']);rememberExample('names',m.wp,m.nameFeature,m.rawName||m.name,name,m.img);m.aliases=[...new Set([...(m.aliases||[]),m.name,m.rawName].filter(Boolean))];m.name=name;m.nameConfirmed=true;if(!await commitChange(change))return;closeDialog();render()}
const delMate=async id=>{if(confirm(T2('Remove this colleague?','این همکار حذف بشه؟'))){const change=beginChange('Colleague removal','حذف همکار',['mates']);S.mates=S.mates.filter(m=>m.id!==id);if(!await commitChange(change))return;render()}};
const noMates=()=>`<div class="c"><b>${T2('No colleagues yet','برنامهٔ همکاران را اضافه کنید')}</b><p class="mu">${T2('Add any colleague roster pages. Your own row is not required.','برای پیدا کردن پیشنهاد تعویض، برنامهٔ همکاران را هم از عکس اضافه کنید.')}</p>${sc.pages&&sc.pages.length?`<button class="p" onclick="readAll()">${T2('Read colleagues from the last scan','خواندن برنامهٔ همکاران')}</button>`:`<button class="p s" onclick="addColleaguePages(${jsArg(sc.wp||S.wps[0]?.id||'')})">${T2('Scan colleague roster','افزودن برنامهٔ همکاران')}</button>`}</div>`;
const mateList=(w,ms)=>`<p class="mu">${T2('Tap a name to correct it and remember it for future scans.','برای اصلاح نام، روی آن بزنید.')}</p>`+ms.map(m=>`<div class="pk"><span style="display:flex;gap:8px;align-items:center">${m.img?`<img class="nm" src="${imageSrc(m.img)}">`:''}<button class="name-edit" onclick="renMate(${jsArg(m.id)})">${bidi(m.name||'?')} <span aria-hidden="true">✎</span></button></span><span class="mu">${Object.values(m.cells).filter(t=>isWork(w,t)).length} ${T2('shifts','شیفت')} <button class="x" onclick="delMate(${jsArg(m.id)})">✕</button></span></div>`).join('')+(sc.pages&&sc.pages.length?`<button class="p s" style="margin-top:6px" onclick="readAll()">${T2('Read colleagues from the last scan','خواندن برنامهٔ همکاران')}</button>`:'');
const coverCard=(r,x)=>`<article class="swap-option" data-hid="${esc(r.h.id)}" data-mid="${esc(x.m.id)}"><div class="option-heading"><b>${bidi(x.m.name)}</b><span class="option-kind">${x.combo?T2('Combined duty','شیفت ترکیبی'):T2('Covers you','جایگزین')}</span></div><p>${T2('You are off; they take your shift.','off میشی؛ همکارت شیفتت رو می‌گیره.')}</p><div class="option-transfer"><span>${T2('Their shift','شیفت همکار')}</span><b>${codeHTML(x.current)} <span aria-hidden="true">→</span> ${codeHTML(x.combo||r.h.text)}</b></div><button class="text-button request-button" onclick="coverRequest(${jsArg(r.h.id)},${jsArg(x.m.id)})">${T2('Prepare a request','متن درخواست')}</button></article>`;
const exchangeCard=(r,x)=>`<article class="swap-option exchange-option" data-hid="${esc(r.h.id)}" data-mid="${esc(x.m.id)}" data-date="${esc(x.date)}"><div class="option-heading"><b>${bidi(x.m.name)}</b><span class="option-kind">${T2('Exchange','دوطرفه')}</span></div><div class="exchange-summary"><p><span>${T2('Your schedule','برنامهٔ شما')}</span><b>${codeHTML(x.take)} · ${dateHTML(x.date)}</b></p><p><span>${T2('Colleague’s schedule','برنامهٔ همکار')}</span><b>${codeHTML(x.give)} · ${dateHTML(r.h.date)}</b></p></div><button class="p s" onclick="exchangePreview(${jsArg(r.h.id)},${jsArg(x.m.id)},${jsArg(x.date)})">${T2('Preview exchange','دیدن تعویض')}</button></article>`;
function groupByColleague(arr){const groups=new Map();for(const x of arr){if(!groups.has(x.m.id))groups.set(x.m.id,[]);groups.get(x.m.id).push(x)}return [...groups.values()]}
function coverResults(R){
 const section=(title,subtitle,arr,fn)=>arr.length?`<section class="option-section"><h2>${title}<span>${arr.length}</span></h2><p class="option-subtitle">${subtitle}</p>${groupByColleague(arr).map(options=>options.map(fn).join('')).join('')}</section>`:'';
 return (R.rows.length>1?`<p class="multi-shift-note">${T2('Each exchange below is a separate choice. Check again after saving one.','برای هر شیفت، یک پیشنهاد انتخاب کنید.')}</p>${R.all.length?`<section class="common-cover"><h2>${T2('Can cover all selected shifts','جایگزین برای همهٔ شیفت‌های انتخاب‌شده')}</h2><p>${R.all.map(m=>bidi(m.name)).join('، ')}</p></section>`:''}`:'')+R.rows.map(r=>{const cover=[...r.free,...r.ext],shownCover=true,shownSwap=true;const pending=[...r.unk,...r.pending],unique=[...new Map(pending.map(x=>[x.m.id+'|'+x.reason+'|'+x.date,x])).values()];return`<section class="shift-options"><div class="selected-shift-heading"><b>${codeHTML(r.h.text)} · ${dateHTML(r.h.date)}</b><span>${T2('Your shift','شیفت شما')}</span></div>`+

 (shownSwap?section(T2('You exchange two shifts','تعویض دوطرفه'),T2('They take yours; you take one of theirs.','برنامه پس از تعویض:'),r.swap,x=>exchangeCard(r,x)):'')+
 (shownCover?section(T2('Someone takes your shift','واگذاری شیفت'),T2('No shift to take in return.','شیفتتان را به همکار واگذار می‌کنید.'),cover,x=>coverCard(r,x)):'')+
 (!(shownCover&&cover.length)&&!(shownSwap&&r.swap.length)?`<div class="c empty-options"><b>${T2('No checked option in this view','پیشنهادی برای این انتخاب پیدا نشد')}</b><p>${T2('Check missing roster dates or colleague preferences.','برنامهٔ همکاران و تنظیماتشان را بررسی کنید.')}</p></div>`:'')+
 (unique.length?`<details class="review-options-note"><summary>${unique.length} ${T2('items need roster review','مورد نیاز به بررسی برنامه')}</summary>${unique.map(x=>`<p><b>${bidi(x.m.name)}</b> · ${dateHTML(x.date||r.h.date)}<br>${esc(swapReason(x))}<button class="text-button" onclick="openRoster(${jsArg(r.h.wp)});roster.cm=mfirst(new Date(${jsArg(x.date||r.h.date)}+'T00:00'));roster.page=Math.floor((${S.cal==='j'?jp(new Date((x.date||r.h.date)+'T00:00')).d:new Date((x.date||r.h.date)+'T00:00').getDate()}-1)/7);editMateCell(${jsArg(x.m.id)},${jsArg(x.date||r.h.date)})">${T2('Check this date','بررسی این روز')}</button></p>`).join('')}<button class="text-button" onclick="openRoster(${jsArg(r.h.wp)})">${T2('Review digital roster','بررسی برنامهٔ دیجیتال')}</button></details>`:'')+
 (r.blocked.length?`<details class="blocked-options"><summary>${T2('Why direct cover is not offered','چرا بعضی همکاران پیشنهاد نشده‌اند؟')}</summary>${r.blocked.map(x=>`<p><b>${bidi(x.m.name)}</b> · ${esc(swapReason(x))}</p>`).join('')}</details>`:'')+`</section>`}).join('');
}

const covV=w=>{const R=tc.res?coverCalc(w,tc.dates):null;if(tc.res)tc.res=R;const my=S.shifts.filter(h=>h.wp===w.id&&h.date>=iso(Date.now())&&h.segs.length).sort((a,b)=>a.date.localeCompare(b.date));
 if(!tc.cm)tc.cm=mfirst(new Date((my[0]?.date||iso(Date.now()))+'T00:00'));
 const first=mfirst(tc.cm),next=mfirst(new Date(first.getFullYear(),first.getMonth(),first.getDate()+32)),visible=my.filter(h=>h.date>=iso(first)&&h.date<iso(next));
 const list=visible.map(h=>`<button class="pk ${tc.dates.includes(h.id)?'on':''}" aria-pressed="${tc.dates.includes(h.id)}" onclick="togD(${jsArg(h.id)})"><span>${dayLabel(h.date)}<small>${h.segs.map(g=>timeRange(g.s,g.e)).join(' · ')}</small></span><b class="code-tag">${codeHTML(h.text)}</b><span>${tc.dates.includes(h.id)?'✓':'+'}</span></button>`).join('');
 const grid=calendarDays(first).map(d=>{if(!d)return'<span></span>';const ds=iso(d),hs=my.filter(h=>h.date===ds),chosen=hs.some(h=>tc.dates.includes(h.id));return `<button class="cell cover-day ${chosen?'sel':''} ${ds===iso(Date.now())?'t':''} ${isWeekend(d)?'holiday':''}" ${hs.length?'':'disabled'} aria-pressed="${chosen}" aria-label="${esc(dlabel(ds))}" onclick="toggleCoverDay(${jsArg(ds)})"><b class="day-number">${S.cal==='j'?jp(d).d:d.getDate()}</b>${hs.slice(0,2).map(h=>shiftMark(w,h.text)).join('')}${chosen?'<span class="selected-dot" aria-hidden="true"></span>':''}</button>`}).join('');
 const picker=`<section class="calendar-panel cover-picker"><div class="row month-heading"><button class="flip" onclick="moveCoverMonth(-1)" aria-label="${T2('Previous month','ماه قبل')}">‹</button><b>${first.toLocaleDateString(loc(),{month:'long',year:'numeric'})}</b><button class="text-button cover-view" onclick="tc.mode=tc.mode==='month'?'list':'month';render()" aria-label="${tc.mode==='month'?T2('List view','نمایش فهرست'):T2('Month view','نمایش ماه')}">${tc.mode==='month'?T2('List','فهرست'):T2('Month','ماه')}</button><button class="flip" onclick="moveCoverMonth(1)" aria-label="${T2('Next month','ماه بعد')}">›</button></div>${tc.mode==='month'?`<div class="grid cover-month">${weekdaysHTML()}${grid}</div>`:`<div class="cover-dates">${list||`<p class="mu">${T2('No work shifts this month.','این ماه شیفت کاری ثبت نشده است.')}</p>`}</div>`}<p class="cover-hint mu">${T2('Tap the shifts you want to hand over.','شیفت‌هایی را که می‌خواهید واگذار کنید انتخاب کنید.')}</p></section>`;
 const btn=`<button class="p cover-submit" onclick="coverGo()" ${tc.dates.length&&mates(w.id).length?'':'disabled'}>${T2('Find shift options','پیدا کردن پیشنهادها')}${tc.dates.length?` · ${tc.dates.length}`:''}</button>`;
 if(!R)return (tc.notice?`<div class="c saved-exchange" role="status"><b>✓ ${bidi(tc.notice)}</b><p>${T2('You can see the updated dates in Calendar and Digital roster.','برنامه به‌روز شد.')}</p></div>`:'')+`<p class="cover-intro">${T2('Select the shift or shifts you want to change.','شیفت یا شیفت‌های مورد نظر خود برای تعویض را انتخاب کنید.')}</p>`+picker+btn+(mates(w.id).length?'':noMates());
 return `<details class="selection-details"><summary>${T2('Change selected shifts','تغییر شیفت‌های انتخاب‌شده')} (${tc.dates.length})</summary>${picker}${btn}</details>`+coverResults(R)};

function calendarDays(first){const key=d=>S.cal==='j'?jp(d).m:d.getMonth(),out=Array((first.getDay()-S.fdow+7)%7).fill(null);for(let d=first;key(d)===key(first);d=new Date(d.getFullYear(),d.getMonth(),d.getDate()+1))out.push(d);return out}
function weekdaysHTML(){return Array.from({length:7},(_,i)=>{const d=new Date(2024,0,7+(i+S.fdow)%7);return `<span class="weekday ${isWeekend(d)?'holiday':''}" title="${d.toLocaleDateString(loc(),{weekday:'long'})}">${weekdayShort(d)}</span>`}).join('')}
function moveCoverMonth(n){const d=mfirst(tc.cm);tc.cm=mfirst(n>0?new Date(d.getFullYear(),d.getMonth(),d.getDate()+32):new Date(d.getFullYear(),d.getMonth(),d.getDate()-1));tc.res=null;render()}
function toggleCoverDay(date){const hs=S.shifts.filter(h=>h.wp===tc.wp&&h.date===date&&h.segs.length),all=hs.every(h=>tc.dates.includes(h.id));for(const h of hs)tc.dates=all?tc.dates.filter(id=>id!==h.id):[...new Set([...tc.dates,h.id])];tc.res=null;render()}
const cmpV=w=>{const ms=mates(w.id),m=ms.find(x=>x.id===tc.mate),sel=`<select onchange="tc.mate=this.value;render()"><option value="">${T2('Choose a colleague','همکار مورد نظر را انتخاب کنید')}</option>${ms.map(x=>`<option value="${esc(x.id)}" ${x.id===tc.mate?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`;
  if(!m)return sel;const mine={};S.shifts.filter(h=>h.wp===w.id).forEach(h=>mine[h.date]=h.text);
  const both=[],a=[],b=[];for(const d of [...new Set([...Object.keys(mine),...Object.keys(m.cells)])].sort()){if((m.uns||[]).includes(d))continue;const x=mine[d]||'',y=m.cells[d]||'',xw=isWork(w,x),yw=isWork(w,y);if(xw&&yw)both.push([d,x,y]);else if(xw&&isOff(w,y))a.push([d,x]);else if(yw&&isOff(w,x))b.push([d,y])}
  const L=(t,arr,f)=>`<h1>${t} (${arr.length})</h1>`+(arr.length?`<div class="c">${arr.map(f).join('<br>')}</div>`:`<div class="c mu">—</div>`);
  return sel+((m.uns||[]).length?`<p class="c scan-notice">${T2('Dates needing scan review are excluded from this comparison.','چند روز از برنامه نیاز به بررسی دارد.')}</p>`:'')+L(T2('Working together','روزهایی که هر دو شیفت دارید'),both,([d,x,y])=>`${dlabel(d)} · ${codeHTML(x)} / ${codeHTML(y)}`)+L(T2('I work, they are off','روزهای off همکار'),a,([d,x])=>`${dlabel(d)} · ${codeHTML(x)}`)+L(T2('They work, I am off','روزهای off شما'),b,([d,y])=>`${dlabel(d)} · ${codeHTML(y)}`)};
V.team=()=>{if(!S.wps.length)return`<div class="empty"><p class="mu">${T2('Add a workplace first.','ابتدا محل کارتان را وارد کنید.')}</p><button class="p" onclick="go('places')">Add workplace</button></div>`;
  const w=curWp();tc.wp=w.id;const ms=mates(w.id);
  if(tc.busy)return`<div class="c"><div class="pbar"><i></i></div><div id="prog" class="mu" style="margin-top:8px"></div><button class="p s" style="margin-top:10px" onclick="tc.cancel=1">${T2('Cancel','لغو')}</button></div>`;
  const wsel=S.wps.length>1?`<select onchange="tc.wp=this.value;tc.res=null;tc.dates=[];tc.month='';tc.cm=null;tc.mate='';render()">${S.wps.map(x=>`<option value="${esc(x.id)}" ${x.id===w.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:'';
  const people=tc.v==='cmp';
  const heading=`<div class="team-heading">${people?`<h1>${T2('Colleague preferences','تنظیمات همکاران')}</h1>`:''}<div class="team-tools">${people?`<button class="text-button" onclick="tc.v='cover';render()">${T2('Back to shift swap','برگشت به تعویض شیفت')}</button>`:`<button class="text-button" onclick="openColleagues()">${T2('Colleague preferences','تنظیمات همکاران')}</button>`}<button class="text-button" onclick="openRoster(${jsArg(w.id)})">${T2('Digital roster','برنامهٔ دیجیتال')}</button></div></div>`;
  return wsel+heading+(people?(!ms.length?noMates():colleaguesV(w)):covV(w))};

// Reads every other row of the last scanned sheet and stores them as colleagues (device only).
const cleanName=s=>(s||'').replace(/[\u200c\u200e\u200f|\[\]_]/g,' ').replace(/\s+/g,' ').trim();
async function readAll(){const w=S.wps.find(x=>x.id===sc.wp);if(!w||!sc.pages)return;const unchecked=sc.pages.findIndex(p=>p.guess);if(unchecked>=0){sc.continueReadAll=true;tab='scan';openDateCheck(unchecked);return}const change=beginChange('Colleague roster','برنامهٔ همکاران',['mates']);tc.busy=true;tc.cancel=false;tc.v='list';tab='team';render();
  try{if(!sc.wk){const B=BASE();await loadScript(B+'tesseract.min.js');sc.wk=await Tesseract.createWorker('eng',1,{workerPath:B+'worker.min.js',corePath:B,langPath:B+'lang',gzip:true})}
    const wk=sc.wk,J=S.cal==='j',b0=J?fromJ(sc.y,sc.m,1):new Date(sc.y,sc.m-1,1),rows=sc.rows.filter((r,i)=>i!==sc.ri);
    await wk.setParameters({tessedit_pageseg_mode:'7',tessedit_char_whitelist:codeTokens(w)});
    for(let q=0;q<rows.length&&!tc.cancel;q++){const r=rows[q];usePage(r.pi);const V=sc.vl,cells={},uns=[],scan={};P(T2('Reading colleague ','در حال خواندن برنامهٔ همکار ')+(q+1)+'/'+rows.length,q/rows.length);
      for(let i=0;i<V.length-1;i++){const day=sc.dayAt(i);if(day<1||day>31||i===sc.nameCol)continue;const d=new Date(b0.getFullYear(),b0.getMonth(),b0.getDate()+day-1);if(!(J?jp(d).m===sc.m:d.getMonth()===sc.m-1))continue;
        const result=await recognizeShift(w,wk,...cellBounds(V[i],r.y0,V[i+1],r.y1)),t=result.text;
        if(sc.guess||result.c<80||result.uncertain||!t||!parse(w,t))uns.push(iso(d));
        scan[iso(d)]=scanEvidence(result);if(t&&parse(w,t))cells[iso(d)]=t;}
      const name=cleanName(r.nm),duplicate=rows.filter(x=>nn(cleanName(x.nm))===nn(name)).length>1,ex=duplicate?null:matchingColleague(w.id,name);
      const meta={img:r.img,rawName:r.rawName||r.nm,nameFeature:r.nameFeature};
      if(ex){for(const date of Object.keys(scan))delete ex.cells[date];Object.assign(ex.cells,cells);ex.uns=[...(ex.uns||[]).filter(x=>!(x in scan)),...uns];ex.scan={...ex.scan,...scan};ex.scan=Object.fromEntries(Object.entries(ex.scan).sort(([a],[b])=>b.localeCompare(a)).slice(0,62));Object.assign(ex,meta)}else(S.mates=S.mates||[]).push({id:'m'+Date.now()+q,wp:w.id,name:name||'#'+(q+1),...meta,cells,uns,scan})}

    }catch(e){alert(T2('Could not finish reading colleagues. Try again.','خواندن برنامهٔ همکاران کامل نشد؛ دوباره تلاش کنید.'))}
  const saved=await commitChange(change);tc.busy=false;await killWk();render();if(!saved)return;roster.review=false;roster.cm=mfirst(S.cal==='j'?fromJ(sc.y,sc.m,1):new Date(sc.y,sc.m-1,1));roster.page=0;openRoster(w.id)}


let roster={wp:'',cm:null,page:0,wide:false,search:'',returnTab:'agenda'};
function openRoster(id){if(id)roster.wp=id;roster.returnTab=['agenda','team','today'].includes(tab)?tab:'agenda';if(!roster.cm)roster.cm=mfirst(cm);go('roster')}
V.roster=()=>{if(!S.wps.length)return noMates();const w=S.wps.find(w=>w.id===roster.wp)||curWp();roster.wp=w.id;if(roster.review)return savedScanReviewV(w);return (S.wps.length>1?`<select aria-label="${T2('Workplace','محل کار')}" onchange="roster.wp=this.value;roster.cm=null;roster.page=0;render()">${S.wps.map(x=>`<option value="${esc(x.id)}" ${w.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:'')+digitalRoster(w)};
function rosterShortcut(w){return `<button class="p" onclick="openRoster(${jsArg(w.id)})">${T2('Open digital roster','باز کردن برنامهٔ دیجیتال')}</button>`}
function digitalRoster(w){if(!roster.cm){const latest=S.shifts.filter(h=>h.wp===w.id).sort((a,b)=>a.date.localeCompare(b.date))[0];roster.cm=mfirst(new Date((latest?.date||iso(Date.now()))+'T00:00'))}const first=mfirst(roster.cm),days=calendarDays(first).filter(Boolean);roster.page=Math.min(roster.page,Math.floor((days.length-1)/7));
 const shown=roster.wide?days:days.slice(roster.page*7,roster.page*7+7),mine=Object.fromEntries(S.shifts.filter(h=>h.wp===w.id).map(h=>[h.date,h])),ms=mates(w.id).filter(m=>!roster.search||nn(m.name).includes(nn(roster.search))),rows=[{id:'self',name:S.myname||T2('You','شما'),cells:Object.fromEntries(Object.values(mine).map(h=>[h.date,h.text])),uns:Object.values(mine).filter(h=>h.review).map(h=>h.date)},...ms];
 const table=`<div class="roster-scroll ${roster.wide?'wide':''}" tabindex="0" aria-label="${T2('Digital roster table','جدول دیجیتال برنامه')}"><table class="roster-table"><thead><tr><th scope="col">${T2('Name','نام')}</th>${shown.map(d=>`<th scope="col" class="${iso(d)===iso(Date.now())?'roster-today':''}"><b>${S.cal==='j'?jp(d).d:d.getDate()}</b><small>${d.toLocaleDateString(loc(),{weekday:'short'})}</small></th>`).join('')}</tr></thead><tbody>${rows.map(m=>`<tr class="${m.id==='self'?'self-row':''}"><th scope="row">${m.id==='self'?`<b>${bidi(m.name)}</b><small>${T2('Your shifts','برنامهٔ شما')}</small>`:`<button class="roster-name" onclick="renMate(${jsArg(m.id)})">${bidi(m.name)}</button>`}</th>${shown.map(d=>{const ds=iso(d),t=m.cells[ds],u=(m.uns||[]).includes(ds);return `<td class="${u?'uncertain-cell':''} ${ds===iso(Date.now())?'roster-today':''}"><button class="roster-cell" onclick="${m.id==='self'?mine[ds]?`editShift(${jsArg(mine[ds].id)})`:`addRosterShift(${jsArg(w.id)},${jsArg(ds)})`:`editMateCell(${jsArg(m.id)},${jsArg(ds)})`}" aria-label="${esc(m.name+' '+dateText(ds)+' '+(t||T2('Unknown','نامشخص')))}">${t?shiftMark(w,t):'<span class="unknown-mark">?</span>'}${u?'<span class="review-dot" aria-label="Needs review">•</span>':''}</button></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;
 return `<section class="c digital-sheet"><div class="row month-heading"><button class="flip" onclick="moveRosterMonth(-1)" aria-label="${T2('Previous month','ماه قبل')}">‹</button><b>${first.toLocaleDateString(loc(),{month:'long',year:'numeric'})}</b><button class="flip" onclick="moveRosterMonth(1)" aria-label="${T2('Next month','ماه بعد')}">›</button></div><input class="roster-search" aria-label="${T2('Search colleague names','جستجوی نام همکار')}" placeholder="${T2('Search colleague names','جستجوی نام همکار')}" value="${esc(roster.search)}" oninput="filterRoster(this.value)"><div class="roster-range"><button class="icon-button flip" ${roster.page===0||roster.wide?'disabled':''} onclick="roster.page--;render()" aria-label="${T2('Previous days','روزهای قبل')}">‹</button><span>${dateHTML(shown[0])} – ${dateHTML(shown.at(-1))}</span><button class="icon-button flip" ${(roster.page+1)*7>=days.length||roster.wide?'disabled':''} onclick="roster.page++;render()" aria-label="${T2('Next days','روزهای بعد')}">›</button></div>${pendingScans(w).length?`<div class="review-entry"><button class="p s" onclick="openScanReview(${jsArg(w.id)})">${T2('Check '+pendingScans(w).length+' unclear shifts','بررسی '+pendingScans(w).length+' شیفت نامشخص')}</button></div>`:''}${table}<div class="roster-actions"><button class="text-button" onclick="addColleaguePages(${jsArg(w.id)})">${T2('Add colleague pages','افزودن صفحه‌های همکاران')}</button><button class="text-button" onclick="openColleagues()">${T2('Colleague preferences','تنظیمات همکاران')}</button><button class="text-button" onclick="roster.wide=!roster.wide;render()">${roster.wide?T2('Fit screen','نمایش متناسب با صفحه'):T2('Whole month','نمایش کل ماه')}</button><button class="text-button" onclick="editWp(${jsArg(w.id)},true)">${T2('Symbol meanings','معنی علامت‌ها')}</button></div><p class="roster-note">${T2('Tap a cell to edit. ? means unknown, not off; dotted cells need review.','برای ویرایش روی خانه بزنید. ؟ یعنی نامشخص؛ خانهٔ نقطه‌دار نیاز به بررسی دارد.')}${roster.wide?T2(' Swipe the table to see all dates.',' برای دیدن همهٔ تاریخ‌ها، جدول را به طرفین بکشید.'):''}</p></section>`+(ms.length?'':noMates())}
function filterRoster(value){roster.search=value;render();const el=$('.roster-search');el?.focus();el?.setSelectionRange(value.length,value.length)}
function moveRosterMonth(n){const d=mfirst(roster.cm);roster.cm=mfirst(n>0?new Date(d.getFullYear(),d.getMonth(),d.getDate()+32):new Date(d.getFullYear(),d.getMonth(),d.getDate()-1));roster.page=0;render()}
function editMateCell(id,date){const m=S.mates.find(m=>m.id===id);if(!m)return;const w=wp(m.wp),text=m.cells[date]||'';showInline(`<h3>${T2('Edit colleague shift','ویرایش شیفت همکار')}</h3><p>${bidi(m.name)} · ${dateHTML(date)}</p>${m.scan?.[date]?.img?`<img class="scan-evidence" src="${imageSrc(m.scan[date].img)}" alt="${T2('Shift from photo','شیفت در عکس')}">`:''}<div class="shift-keys">${presetCodes(w).map(c=>`<button class="shift-key" onclick="$('#mate-code').value=${esc(JSON.stringify(c.code))}"><bdi dir="ltr">${esc(c.code)}</bdi><small>${esc(c.label)}</small></button>`).join('')}</div><input id="mate-code" dir="ltr" autocapitalize="off" value="${esc(canonicalShift(w,text))}" aria-label="${T2('Shift symbol','علامت شیفت')}"><div class="dialog-actions"><button class="p" onclick="saveMateCell(${jsArg(id)},${jsArg(date)})">Save</button><button class="p s" onclick="closeDialog()">${T2('Cancel','لغو')}</button></div><button class="text-button" onclick="clearMateCell(${jsArg(id)},${jsArg(date)})">${T2('Mark as unknown','ثبت به‌عنوان نامشخص')}</button>`,'.roster-range')}
async function saveMateCell(id,date){const m=S.mates.find(m=>m.id===id),t=canonicalShift(wp(m.wp),nrm($('#mate-code').value.trim()));if(!parse(wp(m.wp),t))return alert(T2('Define this symbol first.','ابتدا معنی این علامت را تعریف کنید.'));const change=beginChange('Colleague shift','شیفت همکار',['mates','ocrMemory']);const evidence=m.scan?.[date];if(evidence)rememberExample('glyphs',m.wp,evidence.feature,evidence.raw,t,evidence.img);if(m.scan)delete m.scan[date];m.cells[date]=t;m.uns=(m.uns||[]).filter(d=>d!==date);tc.res=null;if(!await commitChange(change))return;closeDialog();render()}
async function clearMateCell(id,date){const m=S.mates.find(m=>m.id===id);if(!m)return;const change=beginChange('Colleague shift','شیفت همکار',['mates']);delete m.cells[date];if(m.scan)delete m.scan[date];m.uns=(m.uns||[]).filter(d=>d!==date);tc.res=null;if(!await commitChange(change))return;closeDialog();render()}
function addRosterShift(id,date){addShift(date);$('#fw').value=id;chips()}
function editDayShift(){const hs=S.shifts.filter(h=>h.date===sel&&(!calendarWorkplace||h.wp===calendarWorkplace));if(hs.length===1)editShift(hs[0].id);else{addShift(sel);if(calendarWorkplace&&$('#fw')){$('#fw').value=calendarWorkplace;chips()}}}

function loadingProgress(value,text){const screen=$('#loading-screen');if(!screen)return;screen.style.setProperty('--loading-progress',value+'%');if(text)$('#loading-status').textContent=text}
function finishLoading(){const screen=$('#loading-screen');if(!screen)return;setTimeout(()=>{loadingProgress(100,'آماده‌ایم؛ برویم سراغ روزهای شما');setTimeout(()=>{screen.classList.add('ready');setTimeout(()=>screen.remove(),300)},950)},Math.max(0,1100-(Date.now()-bootStarted)))}

(async()=>{try{loadingProgress(12,'داریم برنامه‌تان را باز می‌کنیم…');const L=await load()||{};if(L.wps&&!L.ver){L.lang='fa';L.cal='j';L.ver=3}S={...S,...L};loadingProgress(70,'برنامه‌تان تقریباً آماده است…');normalizeSavedOff();sel=iso(Date.now());cm=mfirst(new Date());render();finishLoading();if('serviceWorker'in navigator){navigator.serviceWorker.register('sw.js').catch(()=>{});if(navigator.serviceWorker.controller)navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload())}}catch(e){const screen=$('#loading-screen');if(screen){$('#loading-status').textContent='برنامهٔ ذخیره‌شده باز نشد. دوباره تلاش کنید.';screen.querySelector('.loading-retry').hidden=false;screen.classList.add('load-error')}}})();
setInterval(()=>tab==='today'&&!$('#dlg').open&&render(),60000);
